//! AST → Go source.
//!
//! One pass over the checked AST. Every expression's Go type comes from
//! the type inty recorded for it during inference (keyed by span), so
//! the emitter never guesses: `a + b` becomes float64 addition or string
//! concatenation depending on what inty proved about `a` and `b`.
//!
//! Layout of the generated file:
//!
//! ```text
//! package main / imports
//! struct declarations      (one per object shape)
//! package-level vars       (top-level `var` / `let` / `const`)
//! top-level functions      (top-level `function` declarations)
//! func main()              (every other top-level statement, in order)
//! runtime helpers          (runtime.go)
//! ```

use std::collections::HashMap;
use std::rc::Rc;

use inty::ast::free_idents::free_identifiers_in_stmt;
use inty::ast::*;
use inty::infer::InferState;
use inty::span::Span;
use inty::types::{TVarName, Type};

use crate::types::{apply_mapping, canonical, resolve, GoType, Mapping, TypeMapper};
use crate::{unsupported, Result};

const RUNTIME: &str = include_str!("runtime.go");

/// Emit a whole program. `state` must be the state that checked
/// `program`, with `expr_types` recording enabled.
pub fn emit_program(program: &Program, state: &mut InferState) -> Result<String> {
    let types = state
        .expr_types
        .take()
        .expect("inty-go: expression-type recording must be enabled before inference");
    let instantiations = state.instantiations.take().unwrap_or_default();
    let mut e = Emitter {
        state,
        types,
        instantiations,
        tm: TypeMapper::default(),
        buf: String::new(),
        indent: 0,
        ret_stack: Vec::new(),
        tmp: 0,
        scopes: vec![HashMap::new()],
        funcs: Vec::new(),
        mappings: vec![Rc::new(Mapping::new())],
        blocks: 0,
        block_stack: Vec::new(),
        deferred: HashMap::new(),
        pure_funcs: HashMap::new(),
    };

    // Bind every top-level name first: function bodies may refer to
    // functions and variables declared further down (hoisting). Top-level
    // functions (declarations and `const f = …` function values) become
    // Go functions, emitted on demand once per instantiation; other
    // top-level bindings become package-level vars.
    let mut globals = String::new();
    for stmt in &program.statements {
        match stmt {
            Stmt::FunctionDecl {
                name,
                params,
                body,
                span,
                ..
            } => {
                let fid = e.register_func(name, params, body, *span, None)?;
                e.bind_func(name, fid);
            }
            Stmt::Var {
                kind, declarations, ..
            } => {
                for d in declarations {
                    if let Some((params, body, span)) = const_function(*kind, d) {
                        let fid = e.register_func(&d.name, params, body, span, None)?;
                        e.bind_func(&d.name, fid);
                        continue;
                    }
                    let t = e.decl_type(d)?;
                    globals.push_str(&format!("var {} {}\n", mangle(&d.name), e.tm.render(&t)));
                    e.bind(&d.name, t);
                }
            }
            Stmt::Import {
                specifiers,
                source,
                span,
            } => e.bind_import(specifiers, source, *span)?,
            _ => {}
        }
    }

    // Everything else runs in `main`, in source order.
    e.indent = 1;
    e.ret_stack.push(GoType::Unit);
    for stmt in &program.statements {
        match stmt {
            Stmt::FunctionDecl { .. } | Stmt::Import { .. } => {}
            Stmt::Var {
                kind, declarations, ..
            } => {
                for d in declarations {
                    if const_function(*kind, d).is_some() {
                        continue;
                    }
                    if let Some(init) = &d.init {
                        let ty = e.decl_type(d)?;
                        let v = e.expr_as(init, &ty)?;
                        e.line(&format!("{} = {}", mangle(&d.name), v));
                    }
                }
            }
            other => e.stmt(other, &[])?,
        }
    }
    e.ret_stack.pop();
    let main_body = std::mem::take(&mut e.buf);

    // Emit every specialisation of a top-level function that something
    // reached; emitting one can request more.
    let mut funcs = String::new();
    while let Some((fid, sid)) = e.next_pending(None) {
        funcs.push_str(&e.emit_top_level_spec(fid, sid)?);
        funcs.push('\n');
    }

    let mut out = String::new();
    out.push_str("// Code generated by `inty go` from type-checked JavaScript. DO NOT EDIT.\n");
    out.push_str("// Requires Go >= 1.22 (per-iteration loop variables, like JS `let`).\n\n");
    out.push_str("package main\n\n");
    out.push_str(
        "import (\n\t\"bufio\"\n\t\"math\"\n\t\"math/bits\"\n\t\"math/rand\"\n\t\"os\"\n\t\"slices\"\n\t\"strconv\"\n\t\"strings\"\n\t\"time\"\n\t\"unicode\"\n)\n\n",
    );
    out.push_str(&e.tm.render_structs());
    if !globals.is_empty() {
        out.push_str(&globals);
        out.push('\n');
    }
    out.push_str(&funcs);
    out.push_str("func main() {\n\tdefer intyOut.Flush()\n");
    out.push_str(&main_body);
    out.push_str("}\n\n");
    out.push_str(RUNTIME);
    Ok(out)
}

/// A `const f = <function>` declarator: bound like a function
/// declaration, so it can be specialised. (`let`/`var` function values
/// may be reassigned, so they stay ordinary variables.)
fn const_function(kind: VarKind, d: &VarDeclarator) -> Option<(&[Param], &Stmt, Span)> {
    match (kind, &d.init) {
        (
            VarKind::Const,
            Some(Expr::Function {
                name: None,
                params,
                body,
                span,
                ..
            }),
        ) => Some((params, body, *span)),
        _ => None,
    }
}

/// What a JS name is bound to, as far as code generation is concerned.
#[derive(Clone)]
enum Bound {
    /// An ordinary variable (or parameter) of this Go type.
    Var(GoType),
    /// A function binding, specialised per instantiation: index into
    /// `Emitter::funcs`.
    Func(usize),
    /// Something imported from a Node built-in module.
    Node(NodeItem),
}

/// The parts of Node's built-in modules the backend implements (see
/// `crates/inty/stdlib/node/*.d.js` for their types). Each lowers to a
/// runtime helper; none is a first-class Go value except `argv`.
#[derive(Clone, Copy, PartialEq, Debug)]
enum NodeItem {
    /// `import * as fs from "node:fs"`
    FsModule,
    /// `import process from "node:process"` (or `* as process`)
    ProcessModule,
    ReadFileSync,
    WriteFileSync,
    AppendFileSync,
    ExistsSync,
    Argv,
    Exit,
    Stdout,
    Stderr,
}

impl NodeItem {
    /// `name` imported from the built-in module `module` (`"node:fs"`,
    /// `"node:process"`; the `node:` prefix is optional).
    fn import(module: &str, name: &str) -> Option<NodeItem> {
        let module = module.strip_prefix("node:").unwrap_or(module);
        Some(match (module, name) {
            ("fs", "readFileSync") => NodeItem::ReadFileSync,
            ("fs", "writeFileSync") => NodeItem::WriteFileSync,
            ("fs", "appendFileSync") => NodeItem::AppendFileSync,
            ("fs", "existsSync") => NodeItem::ExistsSync,
            ("process", "argv") => NodeItem::Argv,
            ("process", "exit") => NodeItem::Exit,
            ("process", "stdout") => NodeItem::Stdout,
            ("process", "stderr") => NodeItem::Stderr,
            _ => return None,
        })
    }

    /// `self.property`, for a module object.
    fn member(self, property: &str) -> Option<NodeItem> {
        match self {
            NodeItem::FsModule => NodeItem::import("fs", property),
            NodeItem::ProcessModule => NodeItem::import("process", property),
            _ => None,
        }
    }
}

/// A function the emitter may specialise.
struct FuncInfo {
    name: String,
    params: Vec<Param>,
    body: Rc<Stmt>,
    /// Span of the function itself, where inty recorded its type.
    span: Span,
    /// Its quantified type variables — those a specialisation fixes.
    qvars: Vec<TVarName>,
    /// The mapping in force where it was declared (an enclosing
    /// function's specialisation); specialisations extend it.
    outer: Rc<Mapping>,
    /// `None` for a top-level Go function; `Some(block)` for a closure
    /// declared in that block.
    block: Option<usize>,
    specs: Vec<Spec>,
}

/// One monomorphic copy of a function.
struct Spec {
    key: String,
    name: String,
    mapping: Rc<Mapping>,
    go_type: GoType,
    emitted: bool,
    /// For closures: the `name = func(...) {...}` text, once emitted.
    text: Option<String>,
}

struct Emitter<'a> {
    state: &'a mut InferState,
    types: HashMap<(usize, usize), Type>,
    /// Per-identifier instantiation of polymorphic bindings (see
    /// `InferState::instantiations`).
    instantiations: HashMap<(usize, usize), Vec<(TVarName, inty::types::Type)>>,
    tm: TypeMapper,
    /// Statement output for the function currently being emitted.
    buf: String,
    indent: usize,
    /// Result type of each enclosing function (innermost last).
    ret_stack: Vec<GoType>,
    /// Counter for fresh temporaries.
    tmp: usize,
    /// Declared Go type of every JS binding in scope, innermost last.
    /// An identifier's type comes from here rather than from the type
    /// recorded at the use site: a use inside a hoisted function can be
    /// recorded as a structural *view* of the binding (e.g. an array seen
    /// as `{length: Number | ρ}`), which isn't the variable's Go type.
    scopes: Vec<HashMap<String, Bound>>,
    /// Every function binding seen so far, with its specialisations.
    funcs: Vec<FuncInfo>,
    /// The specialisation mapping in force, innermost last.
    mappings: Vec<Rc<Mapping>>,
    /// Counter for block ids (closure specialisation markers).
    blocks: usize,
    /// Ids of the blocks being emitted, innermost last.
    block_stack: Vec<usize>,
    /// `const` array pipelines not emitted where declared: their one use,
    /// in the next statement, fuses them into its own loop.
    deferred: HashMap<String, Expr>,
    /// Purity of user functions (see `pure_func`), memoised by name.
    pure_funcs: HashMap<String, bool>,
}

/// A number the emitter can fold at translation time. Folding happens
/// in f64, matching JavaScript; Go would evaluate constant expressions
/// exactly (`0.1 + 0.2` is precisely `0.3` as a Go constant).
fn const_num(e: &Expr) -> Option<f64> {
    match e {
        Expr::Lit {
            value: Literal::Number(n),
            ..
        } => Some(*n),
        Expr::Unary {
            op: UnaryOp::Neg,
            argument,
            ..
        } => const_num(argument).map(|n| -n),
        Expr::Unary {
            op: UnaryOp::Pos,
            argument,
            ..
        } => const_num(argument),
        Expr::Binary {
            op, left, right, ..
        } => {
            let (a, b) = (const_num(left)?, const_num(right)?);
            Some(match op {
                BinOp::Add => a + b,
                BinOp::Sub => a - b,
                BinOp::Mul => a * b,
                BinOp::Div => a / b,
                BinOp::Mod => a % b,
                BinOp::Pow => a.powf(b),
                BinOp::BitAnd => (js_i32(a) & js_i32(b)) as f64,
                BinOp::BitOr => (js_i32(a) | js_i32(b)) as f64,
                BinOp::BitXor => (js_i32(a) ^ js_i32(b)) as f64,
                BinOp::LShift => js_i32(a).wrapping_shl(js_i32(b) as u32 & 31) as f64,
                BinOp::RShift => js_i32(a).wrapping_shr(js_i32(b) as u32 & 31) as f64,
                BinOp::URShift => (js_i32(a) as u32).wrapping_shr(js_i32(b) as u32 & 31) as f64,
                _ => return None,
            })
        }
        Expr::Member {
            object, property, ..
        } => match (&**object, property.as_str()) {
            (Expr::Ident { name, .. }, p) if name == "Math" => math_constant(p),
            (Expr::Ident { name, .. }, p) if name == "Number" => match p {
                "MAX_SAFE_INTEGER" => Some(9007199254740991.0),
                "MIN_SAFE_INTEGER" => Some(-9007199254740991.0),
                "EPSILON" => Some(f64::EPSILON),
                "MAX_VALUE" => Some(f64::MAX),
                "MIN_VALUE" => Some(5e-324),
                _ => None,
            },
            _ => None,
        },
        _ => None,
    }
}

/// ECMAScript ToInt32.
fn js_i32(f: f64) -> i32 {
    if !f.is_finite() {
        return 0;
    }
    (f.trunc().rem_euclid(4294967296.0) as u64) as u32 as i32
}

fn math_constant(name: &str) -> Option<f64> {
    use std::f64::consts;
    Some(match name {
        "PI" => consts::PI,
        "E" => consts::E,
        "LN2" => consts::LN_2,
        "LN10" => consts::LN_10,
        "LOG2E" => consts::LOG2_E,
        "LOG10E" => consts::LOG10_E,
        "SQRT2" => consts::SQRT_2,
        _ => return None,
    })
}

/// Go spelling of a float64 value. Always carries a `.` or exponent so
/// the untyped constant defaults to float64, never int.
fn num_lit(n: f64) -> String {
    if n.is_nan() {
        "math.NaN()".into()
    } else if n.is_infinite() {
        if n > 0.0 {
            "math.Inf(1)"
        } else {
            "math.Inf(-1)"
        }
        .into()
    } else if n == 0.0 && n.is_sign_negative() {
        "math.Copysign(0, -1)".into()
    } else {
        // `{:?}` is the shortest round-trip form: `3.0`, `0.1`, `1e21`.
        let s = format!("{:?}", n);
        if n < 0.0 {
            format!("({})", s)
        } else {
            s
        }
    }
}

/// Go spelling of an integral value as an `int` constant.
fn int_lit(n: f64) -> String {
    let i = n as i64;
    if i < 0 {
        format!("({})", i)
    } else {
        i.to_string()
    }
}

fn is_num(t: &GoType) -> bool {
    matches!(t, GoType::Int | GoType::Float)
}

/// `v`, of Go type `from`, as a value of type `to`: an `Int` flowing into
/// a `Number` slot (the checker's `Int ≤ Number`) becomes a float64. The
/// other direction is a double the checker proved integral (a trap past
/// ±2^53).
fn coerce(v: String, from: &GoType, to: &GoType) -> String {
    match (from, to) {
        (GoType::Int, GoType::Float) => {
            // An int constant: its float spelling.
            let digits = v.trim_start_matches('(').trim_end_matches(')');
            let digits = digits.strip_prefix('-').unwrap_or(digits);
            if !digits.is_empty() && digits.chars().all(|c| c.is_ascii_digit()) {
                format!("{}.0", v.trim_end_matches(')')) + if v.ends_with(')') { ")" } else { "" }
            } else {
                format!("float64({})", v)
            }
        }
        (GoType::Float, GoType::Int) => format!("intyToInt({})", v),
        _ => v,
    }
}

/// ECMAScript ToInt32 / ToUint32 of a number of Go type `t`: a
/// conversion for an `Int` (Go's wraps modulo 2^32, as JS does).
/// (A constant is converted here: Go rejects `uint32(-1)` and would
/// fold `int32(1) << 31` as an overflowing constant.)
fn to_i32(v: String, t: &GoType) -> String {
    if let Some(n) = const_int(&v) {
        return format!("int32({})", js_i32(n as f64));
    }
    match t {
        GoType::Int => format!("int32({})", v),
        _ => format!("intyToInt32({})", v),
    }
}

fn to_u32(v: String, t: &GoType) -> String {
    if let Some(n) = const_int(&v) {
        return format!("uint32({})", js_i32(n as f64) as u32);
    }
    match t {
        GoType::Int => format!("uint32({})", v),
        _ => format!("intyToUint32({})", v),
    }
}

/// The value of an integer (or integral float) literal as spelled by
/// `int_lit` / `num_lit`.
fn const_int(v: &str) -> Option<i64> {
    let inner = v
        .strip_prefix('(')
        .and_then(|x| x.strip_suffix(')'))
        .unwrap_or(v);
    let f: f64 = inner.parse().ok()?;
    (f.is_finite() && f.fract() == 0.0 && f.abs() < 1e15).then_some(f as i64)
}

fn go_string_lit(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 || c as u32 == 0x7f => {
                out.push_str(&format!("\\x{:02x}", c as u32))
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

