/// Go identifier for a JS identifier or property name. Collisions with
/// Go keywords, predeclared names, imported packages and the emitter's
/// own namespaces (`inty*` helpers, `ObjN` structs) get a trailing `_`.
pub fn mangle(name: &str) -> String {
    let mut s = String::new();
    for c in name.chars() {
        if c.is_alphanumeric() || c == '_' {
            s.push(c);
        } else if c == '$' {
            s.push_str("_S");
        } else {
            s.push_str(&format!("_x{:x}", c as u32));
        }
    }
    if s.is_empty() || s.starts_with(|c: char| c.is_ascii_digit()) || s == "_" {
        s.insert(0, '_');
        s.push('_');
    }
    let is_obj = s
        .strip_prefix("Obj")
        .is_some_and(|r| !r.is_empty() && r.chars().all(|c| c.is_ascii_digit()));
    if GO_RESERVED.contains(&s.as_str()) || s.starts_with("inty") || is_obj {
        s.push('_');
    }
    s
}

/// Whether evaluating `e` twice is indistinguishable from once — used
/// before expanding compound assignments that Go can't express directly.
fn is_pure_place(e: &Expr) -> bool {
    match e {
        Expr::Ident { .. } | Expr::Lit { .. } | Expr::This { .. } => true,
        Expr::Member { object, .. } => is_pure_place(object),
        Expr::ComputedMember {
            object, property, ..
        } => is_pure_place(object) && is_pure_place(property),
        _ => false,
    }
}

fn is_terminator(s: &Stmt) -> bool {
    match s {
        Stmt::Break { .. } | Stmt::Continue { .. } | Stmt::Return { .. } | Stmt::Throw { .. } => {
            true
        }
        Stmt::Block { body, .. } => body.last().is_some_and(is_terminator),
        _ => false,
    }
}

impl<'a> Emitter<'a> {
    // ---- output ----------------------------------------------------------

    fn line(&mut self, s: &str) {
        for _ in 0..self.indent {
            self.buf.push('\t');
        }
        self.buf.push_str(s);
        self.buf.push('\n');
    }

    fn pad(&self) -> String {
        "\t".repeat(self.indent)
    }

    fn fresh(&mut self, stem: &str) -> String {
        self.tmp += 1;
        format!("inty{}{}", stem, self.tmp)
    }

    /// Emit statements into a detached buffer one level deeper and
    /// return the text — used for function literals inside expressions.
    fn nested<F>(&mut self, f: F) -> Result<String>
    where
        F: FnOnce(&mut Self) -> Result<()>,
    {
        let saved = std::mem::take(&mut self.buf);
        self.indent += 1;
        let r = f(self);
        self.indent -= 1;
        let body = std::mem::replace(&mut self.buf, saved);
        r.map(|()| body)
    }

    // ---- types -----------------------------------------------------------

    /// The mapping of the specialisation being emitted.
    fn mapping(&self) -> Rc<Mapping> {
        self.mappings.last().cloned().expect("mapping")
    }

    /// `ty` under inty's final substitution and then the current
    /// specialisation's mapping.
    fn in_context(&mut self, ty: &Type) -> Type {
        let r = resolve(self.state, ty);
        apply_mapping(&r, &self.mapping())
    }

    /// The type inty recorded for the node at `span`, in context.
    fn raw_type(&mut self, span: Span) -> Result<Type> {
        match self.types.get(&(span.start, span.end)).cloned() {
            Some(t) => Ok(self.in_context(&t)),
            None => Err(unsupported("expression with no recorded type", span)),
        }
    }

    fn bind(&mut self, name: &str, t: GoType) {
        self.scopes
            .last_mut()
            .expect("scope")
            .insert(name.to_string(), Bound::Var(t));
    }

    fn bind_func(&mut self, name: &str, fid: usize) {
        self.scopes
            .last_mut()
            .expect("scope")
            .insert(name.to_string(), Bound::Func(fid));
    }

    fn lookup(&self, name: &str) -> Option<Bound> {
        self.scopes.iter().rev().find_map(|s| s.get(name)).cloned()
    }

    /// Bind the names a top-level `import` introduces. Only Node's
    /// built-in modules are supported: programs are single files.
    fn bind_import(
        &mut self,
        specifiers: &[ImportSpecifier],
        source: &str,
        span: Span,
    ) -> Result<()> {
        let module = source.strip_prefix("node:").unwrap_or(source);
        if !matches!(module, "fs" | "process") {
            return Err(unsupported(
                format!("import from \"{}\" (only node:fs and node:process)", source),
                span,
            ));
        }
        for sp in specifiers {
            let (local, item) = match sp {
                ImportSpecifier::Named {
                    imported, local, ..
                } => (local, NodeItem::import(module, imported)),
                ImportSpecifier::Default { local, .. } if module == "process" => {
                    (local, Some(NodeItem::ProcessModule))
                }
                ImportSpecifier::Namespace { local, .. } => (
                    local,
                    Some(if module == "fs" {
                        NodeItem::FsModule
                    } else {
                        NodeItem::ProcessModule
                    }),
                ),
                ImportSpecifier::Default { local, .. } => (local, None),
            };
            let Some(item) = item else {
                return Err(unsupported(
                    format!("`{}` from \"{}\"", local, source),
                    span,
                ));
            };
            self.scopes
                .last_mut()
                .expect("scope")
                .insert(local.clone(), Bound::Node(item));
        }
        Ok(())
    }

    /// The Node built-in `e` denotes, if any: an imported name, or a
    /// member of an imported module (`process.stdout`).
    fn node_item(&self, e: &Expr) -> Option<NodeItem> {
        match e {
            Expr::Ident { name, .. } => match self.lookup(name) {
                Some(Bound::Node(item)) => Some(item),
                _ => None,
            },
            Expr::Member {
                object, property, ..
            } => self.node_item(object)?.member(property),
            _ => None,
        }
    }

    fn fn_type(&mut self, span: Span) -> Result<GoType> {
        let t = self.raw_type(span)?;
        self.tm.map(self.state, &t, span)
    }

    /// The Go type of an identifier, and its Go name.
    fn ident(&mut self, name: &str, span: Span) -> Result<Option<(String, GoType)>> {
        match self.lookup(name) {
            Some(Bound::Func(fid)) => self.func_ref(fid, span).map(Some),
            Some(Bound::Node(NodeItem::Argv)) => Ok(Some((
                "intyArgv".into(),
                GoType::Array(Box::new(GoType::Str)),
            ))),
            Some(Bound::Node(item)) => Err(unsupported(
                format!("Node built-in `{}` used as a value ({:?})", name, item),
                span,
            )),
            Some(Bound::Var(t)) => {
                // A generalised non-function value (e.g. an object of
                // polymorphic functions) would need one copy per use type.
                if let Some(inst) = self.instantiations.get(&(span.start, span.end)).cloned() {
                    for (_, t) in &inst {
                        let c = canonical(&self.in_context(t));
                        if c != crate::types::unconstrained() {
                            return Err(unsupported(
                                format!(
                                    "polymorphic value `{}` used at a specific type (only \
                                     functions are specialised; declare it with `function` or `const`)",
                                    name
                                ),
                                span,
                            ));
                        }
                    }
                }
                Ok(Some((mangle(name), t)))
            }
            None => Ok(None),
        }
    }

    fn type_of(&mut self, e: &Expr) -> Result<GoType> {
        if let Expr::Ident { name, span } = e {
            if let Some((_, t)) = self.ident(name, *span)? {
                return Ok(t);
            }
        }
        let span = e.span();
        let t = self.raw_type(span)?;
        self.tm.map(self.state, &t, span)
    }

    fn decl_type(&mut self, d: &VarDeclarator) -> Result<GoType> {
        if let Some(t) = self.state.get_decl_type(d.span).cloned() {
            let t = self.in_context(&t);
            return self.tm.map(self.state, &t, d.span);
        }
        match &d.init {
            Some(init) => self.type_of(init),
            None => Err(unsupported("declaration without an inferred type", d.span)),
        }
    }

    // ---- monomorphisation -------------------------------------------------

    /// Record a function binding. Its quantified variables are the type
    /// variables still free in its (in-context) type.
    fn register_func(
        &mut self,
        name: &str,
        params: &[Param],
        body: &Stmt,
        span: Span,
        block: Option<usize>,
    ) -> Result<usize> {
        let ty = self.raw_type(span)?;
        let mut qvars: Vec<TVarName> = ty
            .free_vars()
            .into_iter()
            .filter(|v| Type::Var(v.clone()) != crate::types::unconstrained())
            .collect();
        qvars.sort_by_key(|v| v.id());
        self.funcs.push(FuncInfo {
            name: name.to_string(),
            params: params.to_vec(),
            body: Rc::new(body.clone()),
            span,
            qvars,
            outer: self.mapping(),
            block,
            specs: Vec::new(),
        });
        Ok(self.funcs.len() - 1)
    }

    /// The specialisation of function `fid` that the identifier at `span`
    /// refers to, requesting it if new: its Go name and type.
    ///
    /// Each quantified variable is fixed by the instantiation inty
    /// recorded at this use. A use with no recorded instantiation is a
    /// monomorphic reference from inside the function's own definition
    /// (recursion), so it inherits the current specialisation's choice.
    fn func_ref(&mut self, fid: usize, span: Span) -> Result<(String, GoType)> {
        let inst = self
            .instantiations
            .get(&(span.start, span.end))
            .cloned()
            .unwrap_or_default();
        // The scheme can also quantify variables its type doesn't mention
        // (determined by a predicate: the element of an `Indexable`
        // parameter, the result of a `HasProp`); the instantiation fixes
        // those too.
        let mut qvars = self.funcs[fid].qvars.clone();
        for (q, _) in &inst {
            if !qvars.contains(q) {
                qvars.push(q.clone());
            }
        }
        // Those an earlier use fixed, too: a recursive use records no
        // instantiation for them, and inherits the current choice (below).
        let outer = self.funcs[fid].outer.clone();
        let mut earlier: Vec<TVarName> = Vec::new();
        for spec in &self.funcs[fid].specs {
            for v in spec.mapping.keys() {
                if !outer.contains_key(v) && !qvars.contains(v) && !earlier.contains(v) {
                    earlier.push(v.clone());
                }
            }
        }
        earlier.sort_by_key(|v| v.id());
        qvars.extend(earlier);
        let mut concrete = Vec::with_capacity(qvars.len());
        for v in &qvars {
            let t = match inst.iter().find(|(q, _)| q == v) {
                Some((_, t)) => t.clone(),
                None => Type::Var(v.clone()),
            };
            concrete.push(canonical(&self.in_context(&t)));
        }
        let key = format!("{}", Type::Tuple(concrete.clone()));
        if let Some(spec) = self.funcs[fid].specs.iter().find(|s| s.key == key) {
            return Ok((spec.name.clone(), spec.go_type.clone()));
        }
        let mut mapping = (*self.funcs[fid].outer).clone();
        for (v, t) in qvars.iter().zip(concrete) {
            mapping.insert(v.clone(), t);
        }
        let mapping = Rc::new(mapping);
        self.mappings.push(mapping.clone());
        let go_type = self.fn_type(self.funcs[fid].span);
        self.mappings.pop();
        let go_type = go_type?;
        let info = &mut self.funcs[fid];
        let base = mangle(&info.name);
        let name = match info.specs.len() {
            0 => base,
            n => format!("{}__{}", base, n + 1),
        };
        info.specs.push(Spec {
            key,
            name: name.clone(),
            mapping,
            go_type: go_type.clone(),
            emitted: false,
            text: None,
        });
        Ok((name, go_type))
    }

    /// A requested but not yet emitted specialisation of a function
    /// owned by `block` (`None`: top level).
    fn next_pending(&self, block: Option<usize>) -> Option<(usize, usize)> {
        self.funcs.iter().enumerate().find_map(|(fid, f)| {
            if f.block != block {
                return None;
            }
            f.specs
                .iter()
                .position(|s| !s.emitted)
                .map(|sid| (fid, sid))
        })
    }

    /// `func name(params) result { body }` for a top-level function.
    fn emit_top_level_spec(&mut self, fid: usize, sid: usize) -> Result<String> {
        self.funcs[fid].specs[sid].emitted = true;
        let (params, body, span) = {
            let f = &self.funcs[fid];
            (f.params.clone(), f.body.clone(), f.span)
        };
        let (name, mapping) = {
            let s = &self.funcs[fid].specs[sid];
            (s.name.clone(), s.mapping.clone())
        };
        // A top-level function sees only the global scope.
        let inner_scopes = self.scopes.split_off(1);
        let saved_buf = std::mem::take(&mut self.buf);
        let saved_indent = std::mem::replace(&mut self.indent, 0);
        self.mappings.push(mapping);
        let r = (|| -> Result<()> {
            let (sig, ptys, ret) = self.signature(&params, span)?;
            self.line(&format!(
                "func {}({}){} {{",
                name,
                sig,
                self.tm.render_result(&ret)
            ));
            self.indent += 1;
            self.function_body(&params, &ptys, &body, &ret)?;
            self.indent -= 1;
            self.line("}");
            Ok(())
        })();
        self.mappings.pop();
        self.indent = saved_indent;
        let text = std::mem::replace(&mut self.buf, saved_buf);
        self.scopes.extend(inner_scopes);
        r.map(|()| text)
    }

    /// `name = func(params) result {...}` for a closure specialisation,
    /// emitted in the scope of its declaring block.
    fn emit_closure_spec(&mut self, fid: usize, sid: usize) -> Result<()> {
        self.funcs[fid].specs[sid].emitted = true;
        let (params, body, span) = {
            let f = &self.funcs[fid];
            (f.params.clone(), f.body.clone(), f.span)
        };
        let (name, mapping) = {
            let s = &self.funcs[fid].specs[sid];
            (s.name.clone(), s.mapping.clone())
        };
        self.mappings.push(mapping);
        let lit = self.func_literal(&params, &body, span);
        self.mappings.pop();
        self.funcs[fid].specs[sid].text = Some(format!("{} = {}", name, lit?));
        Ok(())
    }

    /// Go parameter list and result type for a function at `span`.
    fn signature(&mut self, params: &[Param], span: Span) -> Result<(String, Vec<GoType>, GoType)> {
        let t = self.raw_type(span)?;
        let (ps, ret) = match self.tm.map(self.state, &t, span)? {
            GoType::Func(ps, ret) => (ps, *ret),
            other => {
                return Err(unsupported(
                    format!("function whose type maps to {}", self.tm.render(&other)),
                    span,
                ))
            }
        };
        if ps.len() != params.len() {
            return Err(unsupported("optional or defaulted parameters", span));
        }
        let rendered: Vec<String> = params
            .iter()
            .zip(&ps)
            .map(|(p, t)| format!("{} {}", mangle(&p.name), self.tm.render(t)))
            .collect();
        Ok((rendered.join(", "), ps, ret))
    }

    fn function_body(
        &mut self,
        params: &[Param],
        ptys: &[GoType],
        body: &Stmt,
        ret: &GoType,
    ) -> Result<()> {
        self.scopes.push(HashMap::new());
        for (p, t) in params.iter().zip(ptys) {
            self.bind(&p.name, t.clone());
        }
        self.ret_stack.push(ret.clone());
        let stmts: &[Stmt] = match body {
            Stmt::Block { body, .. } => body,
            other => std::slice::from_ref(other),
        };
        self.block_stmts(stmts)?;
        if *ret != GoType::Unit && !stmts.last().is_some_and(is_terminator) {
            // inty proved control can't fall off the end (otherwise the
            // result type would include `undefined`); Go's syntactic
            // terminating-statement check can't always see that.
            self.line("panic(\"unreachable\")");
        }
        self.ret_stack.pop();
        self.scopes.pop();
        Ok(())
    }

    fn func_literal(&mut self, params: &[Param], body: &Stmt, span: Span) -> Result<String> {
        let (sig, ptys, ret) = self.signature(params, span)?;
        let text = self.nested(|e| e.function_body(params, &ptys, body, &ret))?;
        Ok(format!(
            "func({}){} {{\n{}{}}}",
            sig,
            self.tm.render_result(&ret),
            text,
            self.pad()
        ))
    }

    // ---- statements --------------------------------------------------------

    /// Emit a statement list that forms one Go block. Nested function
    /// declarations are declared up front (JS hoists them).
    fn block_stmts(&mut self, stmts: &[Stmt]) -> Result<()> {
        self.scopes.push(HashMap::new());
        let r = self.block_stmts_in_scope(stmts);
        self.scopes.pop();
        r
    }

    /// A block's statements. Functions declared in it become closures,
    /// one per specialisation the code reaches. Which specialisations
    /// exist is only known once the whole block has been emitted, so the
    /// block leaves markers — one for the `var` declarations at its top
    /// (JS hoists function declarations) and one per function where it is
    /// declared — and fills them in at the end.
    fn block_stmts_in_scope(&mut self, stmts: &[Stmt]) -> Result<()> {
        self.blocks += 1;
        let block = self.blocks;
        self.block_stack.push(block);
        let r = self.block_body_with_markers(stmts, block);
        self.block_stack.pop();
        r
    }

    fn block_body_with_markers(&mut self, stmts: &[Stmt], block: usize) -> Result<()> {
        for s in stmts {
            if let Stmt::FunctionDecl {
                name,
                params,
                body,
                span,
                ..
            } = s
            {
                let fid = self.register_func(name, params, body, *span, Some(block))?;
                self.bind_func(name, fid);
            }
        }
        let decl_marker = format!("\u{1}D{}\u{1}", block);
        self.line(&decl_marker);
        let mut deferred_here = Vec::new();
        for (i, s) in stmts.iter().enumerate() {
            if let Some((name, init)) = self.fusible_intermediate(s, &stmts[i + 1..]) {
                self.deferred.insert(name.clone(), init);
                deferred_here.push(name);
                continue;
            }
            self.stmt(s, &stmts[i + 1..])?;
        }
        for name in deferred_here {
            self.deferred.remove(&name);
        }
        while let Some((fid, sid)) = self.next_pending(Some(block)) {
            self.emit_closure_spec(fid, sid)?;
        }
        let pad = self.pad();
        let mut decls = String::new();
        for fid in 0..self.funcs.len() {
            if self.funcs[fid].block != Some(block) {
                continue;
            }
            let mut assigns = String::new();
            for spec in &self.funcs[fid].specs {
                let t = self.tm.render(&spec.go_type);
                decls.push_str(&format!("{}var {} {}\n", pad, spec.name, t));
                if let Some(text) = &spec.text {
                    assigns.push_str(&format!("{}{}\n", pad, text));
                }
            }
            let marker = format!("{}\u{1}A{}\u{1}\n", pad, fid);
            self.buf = self.buf.replacen(&marker, &assigns, 1);
        }
        let marker = format!("{}{}\n", pad, decl_marker);
        self.buf = self.buf.replacen(&marker, &decls, 1);
        Ok(())
    }

    fn stmt(&mut self, s: &Stmt, rest: &[Stmt]) -> Result<()> {
        match s {
            Stmt::Empty { .. } => {}
            Stmt::Block { body, .. } => {
                self.line("{");
                self.indent += 1;
                self.block_stmts(body)?;
                self.indent -= 1;
                self.line("}");
            }
            Stmt::Expr { expression, .. } => self.expr_stmt(expression)?,
            Stmt::Var {
                kind, declarations, ..
            } => {
                for (i, d) in declarations.iter().enumerate() {
                    if let Some((params, body, span)) = const_function(*kind, d) {
                        let block = self.block_stack.last().copied();
                        let fid = self.register_func(&d.name, params, body, span, block)?;
                        self.bind_func(&d.name, fid);
                        self.line(&format!("\u{1}A{}\u{1}", fid));
                        continue;
                    }
                    let ty = self.decl_type(d)?;
                    let name = mangle(&d.name);
                    let rendered = self.tm.render(&ty);
                    match &d.init {
                        // A function value may refer to itself: declare
                        // first so the literal can capture the variable.
                        Some(init @ Expr::Function { .. }) => {
                            self.line(&format!("var {} {}", name, rendered));
                            self.bind(&d.name, ty.clone());
                            let v = self.expr(init)?;
                            self.line(&format!("{} = {}", name, v));
                        }
                        Some(init) => {
                            let v = self.expr_as(init, &ty)?;
                            self.line(&format!("var {} {} = {}", name, rendered, v));
                        }
                        None => self.line(&format!("var {} {}", name, rendered)),
                    }
                    self.bind(&d.name, ty.clone());
                    // Go rejects unused locals; JS doesn't care.
                    let used_later = declarations[i + 1..]
                        .iter()
                        .filter_map(|d| d.init.as_ref())
                        .any(|e| {
                            inty::ast::free_idents::free_identifiers_in_expr(e).contains(&d.name)
                        })
                        || rest
                            .iter()
                            .any(|s| free_identifiers_in_stmt(s).contains(&d.name));
                    if !used_later {
                        self.line(&format!("_ = {}", name));
                    }
                }
            }
            Stmt::FunctionDecl { name, span, .. } => {
                // Registered by `block_stmts_in_scope`; its specialisations
                // are assigned here once the block is complete.
                match self.lookup(name) {
                    Some(Bound::Func(fid)) => self.line(&format!("\u{1}A{}\u{1}", fid)),
                    _ => return Err(unsupported("function declaration in this position", *span)),
                }
            }
            Stmt::Return { argument, span } => {
                let ret = self.ret_stack.last().cloned().unwrap_or(GoType::Unit);
                match (argument, &ret) {
                    (None, _) => self.line("return"),
                    (Some(a), GoType::Unit) => {
                        return Err(unsupported(
                            "returning a value of type undefined",
                            a.span().merge(*span),
                        ))
                    }
                    (Some(a), ret) => {
                        let v = self.expr_as(a, ret)?;
                        self.line(&format!("return {}", v));
                    }
                }
            }
            Stmt::If {
                test,
                consequent,
                alternate,
                ..
            } => {
                let c = self.cond(test)?;
                self.line(&format!("if {} {{", c));
                self.sub_block(consequent)?;
                let mut alt = alternate.as_deref();
                while let Some(a) = alt {
                    match a {
                        Stmt::If {
                            test,
                            consequent,
                            alternate,
                            ..
                        } => {
                            let c = self.cond(test)?;
                            self.line(&format!("}} else if {} {{", c));
                            self.sub_block(consequent)?;
                            alt = alternate.as_deref();
                        }
                        other => {
                            self.line("} else {");
                            self.sub_block(other)?;
                            alt = None;
                        }
                    }
                }
                self.line("}");
            }
            Stmt::While { test, body, .. } => {
                if matches!(
                    test,
                    Expr::Lit {
                        value: Literal::Boolean(true),
                        ..
                    }
                ) {
                    self.line("for {");
                } else {
                    let c = self.cond(test)?;
                    self.line(&format!("for {} {{", c));
                }
                self.sub_block(body)?;
                self.line("}");
            }
            Stmt::DoWhile { body, test, .. } => {
                // `continue` must still evaluate the test, which is what
                // a Go `for` post statement + condition gives us.
                let first = self.fresh("First");
                let c = self.cond(test)?;
                self.line(&format!(
                    "for {first} := true; {first} || {c}; {first} = false {{"
                ));
                self.sub_block(body)?;
                self.line("}");
            }
            Stmt::For {
                init,
                test,
                update,
                body,
                span,
            } => self.for_stmt(init.as_ref(), test.as_ref(), update.as_ref(), body, *span)?,
            Stmt::ForOf {
                left, right, body, ..
            } => {
                let elem = match self.type_of(right)? {
                    GoType::Array(e) => *e,
                    _ => return Err(unsupported("for-of over a non-array", right.span())),
                };
                self.scopes.push(HashMap::new());
                let arr = self.fresh("Arr");
                let idx = self.fresh("I");
                let a = self.expr(right)?;
                self.line("{");
                self.indent += 1;
                self.line(&format!("{arr} := {a}"));
                self.line(&format!("for {idx} := 0; {idx} < len(*{arr}); {idx}++ {{"));
                self.indent += 1;
                match left {
                    ForInLhs::VarDecl(name, _, _) => {
                        let n = mangle(name);
                        let t = self.tm.render(&elem);
                        self.line(&format!("var {n} {t} = (*{arr})[{idx}]"));
                        self.line(&format!("_ = {n}"));
                        self.bind(name, elem.clone());
                    }
                    ForInLhs::Expr(target) => {
                        let place = self.place(target)?;
                        self.line(&format!("{place} = (*{arr})[{idx}]"));
                    }
                }
                self.block_body(body)?;
                self.indent -= 1;
                self.line("}");
                self.indent -= 1;
                self.line("}");
                self.scopes.pop();
            }
            Stmt::Break { label, .. } => match label {
                Some(l) => self.line(&format!("break {}", mangle(l))),
                None => self.line("break"),
            },
            Stmt::Continue { label, .. } => match label {
                Some(l) => self.line(&format!("continue {}", mangle(l))),
                None => self.line("continue"),
            },
            Stmt::Labeled { label, body, .. } => {
                let saved = self.indent;
                self.indent = self.indent.saturating_sub(1);
                self.line(&format!("{}:", mangle(label)));
                self.indent = saved;
                self.stmt(body, rest)?;
            }
            Stmt::Switch {
                discriminant,
                cases,
                span,
            } => self.switch_stmt(discriminant, cases, *span)?,
            Stmt::Throw { span, .. } => return Err(unsupported("throw", *span)),
            Stmt::Try { span, .. } => return Err(unsupported("try/catch", *span)),
            Stmt::ForIn { span, .. } => return Err(unsupported("for-in", *span)),
            Stmt::Import { span, .. } | Stmt::Export { span, .. } => {
                return Err(unsupported("ES modules (single-file programs only)", *span))
            }
        }
        Ok(())
    }

    /// The body of a compound statement, as the contents of a Go block.
    fn sub_block(&mut self, s: &Stmt) -> Result<()> {
        self.indent += 1;
        self.block_body(s)?;
        self.indent -= 1;
        Ok(())
    }

    fn block_body(&mut self, s: &Stmt) -> Result<()> {
        match s {
            Stmt::Block { body, .. } => self.block_stmts(body),
            other => self.block_stmts(std::slice::from_ref(other)),
        }
    }

    fn for_stmt(
        &mut self,
        init: Option<&ForInit>,
        test: Option<&Expr>,
        update: Option<&Expr>,
        body: &Stmt,
        _span: Span,
    ) -> Result<()> {
        self.scopes.push(HashMap::new());
        let r = self.for_stmt_in_scope(init, test, update, body);
        self.scopes.pop();
        r
    }

    fn for_stmt_in_scope(
        &mut self,
        init: Option<&ForInit>,
        test: Option<&Expr>,
        update: Option<&Expr>,
        body: &Stmt,
    ) -> Result<()> {
        let mut pre = Vec::new();
        let init_s = match init {
            None => String::new(),
            Some(ForInit::Expr(e)) => self.simple_stmt(e)?,
            Some(ForInit::VarDecl(decls)) => {
                // `let` in a for header is per-iteration in JS and (since
                // Go 1.22) in Go, so `:=` in the init clause matches.
                let mut names = Vec::new();
                let mut vals = Vec::new();
                for d in decls {
                    let ty = self.decl_type(d)?;
                    let v = match &d.init {
                        Some(init) => self.expr_as(init, &ty)?,
                        None => return Err(unsupported("uninitialised for-loop variable", d.span)),
                    };
                    let v = match &ty {
                        GoType::Float | GoType::Int | GoType::Str | GoType::Bool => v,
                        _ if v == "nil" => {
                            return Err(unsupported("null-initialised for-loop variable", d.span))
                        }
                        _ => v,
                    };
                    names.push(mangle(&d.name));
                    vals.push(v);
                    pre.push(d.name.clone());
                    self.bind(&d.name, ty);
                }
                format!("{} := {}", names.join(", "), vals.join(", "))
            }
        };
        let test_s = match test {
            Some(t) => self.cond(t)?,
            None => String::new(),
        };
        let update_s = match update {
            Some(u) => self.simple_stmt(u)?,
            None => String::new(),
        };
        if init_s.is_empty() && update_s.is_empty() {
            if test_s.is_empty() {
                self.line("for {");
            } else {
                self.line(&format!("for {} {{", test_s));
            }
        } else {
            self.line(&format!("for {}; {}; {} {{", init_s, test_s, update_s));
        }
        self.indent += 1;
        // A header variable nothing reads would be a Go compile error.
        for name in &pre {
            let used = test.is_some_and(|t| {
                inty::ast::free_idents::free_identifiers_in_expr(t).contains(name)
            }) || update.is_some_and(|u| {
                inty::ast::free_idents::free_identifiers_in_expr(u).contains(name)
            }) || free_identifiers_in_stmt(body).contains(name);
            if !used {
                self.line(&format!("_ = {}", mangle(name)));
            }
        }
        self.block_body(body)?;
        self.indent -= 1;
        self.line("}");
        Ok(())
    }

    fn switch_stmt(&mut self, disc: &Expr, cases: &[SwitchCase], _span: Span) -> Result<()> {
        let mut dt = self.type_of(disc)?;
        let d = self.expr(disc)?;
        // An `Int` discriminant with a fractional case compares as doubles.
        let d = if dt == GoType::Int {
            let mut fractional = false;
            for c in cases.iter().filter_map(|c| c.test.as_ref()) {
                fractional |= self.type_of(c)? == GoType::Float;
            }
            if fractional {
                dt = GoType::Float;
                coerce(d, &GoType::Int, &GoType::Float)
            } else {
                d
            }
        } else {
            d
        };
        self.line(&format!("switch {} {{", d));
        let mut pending: Vec<String> = Vec::new();
        for (i, case) in cases.iter().enumerate() {
            match &case.test {
                Some(t) => {
                    let v = self.expr_as(t, &dt)?;
                    pending.push(v);
                }
                None if !pending.is_empty() => {
                    return Err(unsupported("`case` falling into `default`", case.span))
                }
                None => {}
            }
            if case.consequent.is_empty() && i + 1 < cases.len() {
                continue; // grouped labels: `case 1: case 2: ...`
            }
            if case.test.is_none() {
                self.line("default:");
            } else {
                self.line(&format!("case {}:", pending.join(", ")));
            }
            pending.clear();
            self.indent += 1;
            let mut body: &[Stmt] = &case.consequent;
            if let Some(Stmt::Break { label: None, .. }) = body.last() {
                body = &body[..body.len() - 1];
            }
            // Block-scoped declarations in a case need their own scope
            // in Go only if they'd collide; the case clause already is one.
            self.block_stmts(body)?;
            let ends = case.consequent.last().is_some_and(is_terminator);
            if !ends && i + 1 < cases.len() {
                self.line("fallthrough");
            }
            self.indent -= 1;
        }
        self.line("}");
        Ok(())
    }

    /// An expression in statement position.
    fn expr_stmt(&mut self, e: &Expr) -> Result<()> {
        match e {
            Expr::Conditional {
                test,
                consequent,
                alternate,
                ..
            } => {
                let c = self.cond(test)?;
                self.line(&format!("if {} {{", c));
                self.indent += 1;
                self.expr_stmt(consequent)?;
                self.indent -= 1;
                self.line("} else {");
                self.indent += 1;
                self.expr_stmt(alternate)?;
                self.indent -= 1;
                self.line("}");
            }
            Expr::Binary {
                op: op @ (BinOp::And | BinOp::Or),
                left,
                right,
                ..
            } => {
                let c = self.cond(left)?;
                let c = if *op == BinOp::And {
                    c
                } else {
                    format!("!{}", c)
                };
                self.line(&format!("if {} {{", c));
                self.indent += 1;
                self.expr_stmt(right)?;
                self.indent -= 1;
                self.line("}");
            }
            Expr::Sequence { expressions, .. } => {
                for x in expressions {
                    self.expr_stmt(x)?;
                }
            }
            _ => {
                let s = self.simple_stmt(e)?;
                self.line(&s);
            }
        }
        Ok(())
    }

    /// A Go "simple statement" (assignment, inc/dec, call) for `e`.
    fn simple_stmt(&mut self, e: &Expr) -> Result<String> {
        match e {
            Expr::Assign {
                op, left, right, ..
            } => self.assign_stmt(*op, left, right),
            Expr::Unary {
                op: op @ (UnaryOp::PreInc | UnaryOp::PostInc | UnaryOp::PreDec | UnaryOp::PostDec),
                argument,
                ..
            } => {
                let p = self.place(argument)?;
                let inc = matches!(op, UnaryOp::PreInc | UnaryOp::PostInc);
                Ok(format!("{}{}", p, if inc { "++" } else { "--" }))
            }
            Expr::Call {
                callee,
                arguments,
                span,
                ..
            } => {
                if let Some(v) = self.fused(e)? {
                    return Ok(v);
                }
                // `arr.push(x)` as a statement: append in place.
                if let Expr::Member {
                    object, property, ..
                } = &**callee
                {
                    if property == "push" && arguments.len() == 1 && is_pure_place(object) {
                        if let GoType::Array(elem) = self.type_of(object)? {
                            let a = self.expr(object)?;
                            let v = self.expr_as(&arguments[0], &elem)?;
                            return Ok(format!("intyAppend({a}, {v})"));
                        }
                    }
                }
                self.call(callee, arguments, *span, true)
            }
            other => {
                let v = self.expr(other)?;
                Ok(format!("_ = {}", v))
            }
        }
    }

    fn assign_stmt(&mut self, op: AssignOp, left: &Expr, right: &Expr) -> Result<String> {
        let lt = self.type_of(left)?;
        // Plain element store: JS grows the array on `a[a.length] = v`.
        if op == AssignOp::Assign {
            if let Expr::ComputedMember {
                object, property, ..
            } = left
            {
                if let GoType::Array(elem) = self.type_of(object)? {
                    let a = self.expr(object)?;
                    let i = self.index(property)?;
                    let v = self.expr_as(right, &elem)?;
                    return Ok(format!("intySet({a}, {i}, {v})"));
                }
            }
        }
        let p = self.place(left)?;
        // A bitwise operand keeps its own type (`n |= x` on a Number `n`).
        let bitwise = matches!(
            op,
            AssignOp::BitAndAssign
                | AssignOp::BitOrAssign
                | AssignOp::BitXorAssign
                | AssignOp::LShiftAssign
                | AssignOp::RShiftAssign
                | AssignOp::URShiftAssign
        );
        let (r, r_t) = if bitwise {
            let t = self.type_of(right)?;
            (self.expr(right)?, t)
        } else {
            (self.expr_as(right, &lt)?, lt.clone())
        };
        let direct = |o: &str| Ok(format!("{} {} {}", p, o, r));
        match op {
            AssignOp::Assign => direct("="),
            AssignOp::AddAssign if lt == GoType::Str => direct("+="),
            AssignOp::AddAssign => direct("+="),
            AssignOp::SubAssign => direct("-="),
            AssignOp::MulAssign if lt == GoType::Int => {
                if !is_pure_place(left) {
                    return Err(unsupported(
                        "compound assignment to a place with side effects",
                        left.span(),
                    ));
                }
                Ok(format!("{p} = intyIMul({p}, {r})"))
            }
            AssignOp::MulAssign => direct("*="),
            AssignOp::ModAssign if lt == GoType::Int => direct("%="),
            AssignOp::DivAssign if const_num(right) == Some(0.0) => {
                Ok(format!("{} /= intyZero", p))
            }
            AssignOp::DivAssign => direct("/="),
            _ => {
                if !is_pure_place(left) {
                    return Err(unsupported(
                        "compound assignment to a place with side effects",
                        left.span(),
                    ));
                }
                let (pi, pu) = (to_i32(p.clone(), &lt), to_u32(p.clone(), &lt));
                let (ri, ru) = (to_i32(r.clone(), &r_t), to_u32(r.clone(), &r_t));
                let bits = |s: String| coerce(s, &GoType::Int, &lt);
                let v = match op {
                    AssignOp::ModAssign => format!("intyMod({p}, {r})"),
                    AssignOp::PowAssign => format!("intyPow({p}, {r})"),
                    AssignOp::BitAndAssign => bits(format!("int({pi} & {ri})")),
                    AssignOp::BitOrAssign => bits(format!("int({pi} | {ri})")),
                    AssignOp::BitXorAssign => bits(format!("int({pi} ^ {ri})")),
                    AssignOp::LShiftAssign => bits(format!("int({pi} << ({ru} & 31))")),
                    AssignOp::RShiftAssign => bits(format!("int({pi} >> ({ru} & 31))")),
                    AssignOp::URShiftAssign => bits(format!("int({pu} >> ({ru} & 31))")),
                    _ => return Err(unsupported("logical assignment operator", left.span())),
                };
                Ok(format!("{} = {}", p, v))
            }
        }
    }

    /// An assignable Go expression for `e`.
    fn place(&mut self, e: &Expr) -> Result<String> {
        match e {
            Expr::Ident { .. } | Expr::Member { .. } => self.expr(e),
            Expr::ComputedMember {
                object, property, ..
            } => match self.type_of(object)? {
                GoType::Array(_) => {
                    let a = self.expr(object)?;
                    let i = self.index(property)?;
                    Ok(format!("(*{})[{}]", a, i))
                }
                _ => Err(unsupported("indexed assignment to a non-array", e.span())),
            },
            _ => Err(unsupported("assignment target", e.span())),
        }
    }

    // ---- expressions ---------------------------------------------------

    /// A Go `bool` for a JS condition, applying JS truthiness.
    fn cond(&mut self, e: &Expr) -> Result<String> {
        let t = self.type_of(e)?;
        let v = self.expr(e)?;
        self.truthy(v, &t, e.span())
    }

    fn truthy(&self, v: String, t: &GoType, span: Span) -> Result<String> {
        Ok(match t {
            GoType::Bool => v,
            GoType::Float => format!("intyTruthy({})", v),
            GoType::Int => format!("({} != 0)", v),
            GoType::Str => format!("({} != \"\")", v),
            GoType::Array(_) | GoType::Struct(_) | GoType::Func(..) => format!("({} != nil)", v),
            _ => return Err(unsupported("condition of this type", span)),
        })
    }

    /// Index expression for a slice.
    fn index(&mut self, e: &Expr) -> Result<String> {
        if let Some(n) = const_num(e) {
            if n >= 0.0 && n.fract() == 0.0 && n < 1e15 {
                return Ok(format!("{}", n as i64));
            }
        }
        let t = self.type_of(e)?;
        let v = self.expr(e)?;
        Ok(match t {
            GoType::Int => v,
            _ => format!("int({})", v),
        })
    }

    /// `e`, where the context expects a value of type `want`. Only
    /// differs from [`Self::expr`] for `null`/`undefined`, whose own
    /// recorded type says nothing about which Go type the nil is.
    fn expr_as(&mut self, e: &Expr, want: &GoType) -> Result<String> {
        match e {
            Expr::Lit {
                value: Literal::Null | Literal::Undefined,
                span,
            } => {
                if want.is_nullable() {
                    Ok("nil".into())
                } else {
                    Err(unsupported(
                        "null/undefined where a primitive is expected",
                        *span,
                    ))
                }
            }
            Expr::Ident { name, span } if name == "undefined" => {
                if want.is_nullable() {
                    Ok("nil".into())
                } else {
                    Err(unsupported(
                        "undefined where a primitive is expected",
                        *span,
                    ))
                }
            }
            _ if is_num(want) => self.num_as(e, want),
            _ => self.expr(e),
        }
    }

    /// A number-valued `e` as a Go value of type `want` (`Int` or
    /// `Number`): a constant is spelled in that type, anything else
    /// converted.
    fn num_as(&mut self, e: &Expr, want: &GoType) -> Result<String> {
        if let Some(n) = const_num(e) {
            if *want == GoType::Float || !crate::types::is_int(n) {
                return Ok(num_lit(n));
            }
            return Ok(int_lit(n));
        }
        let t = self.type_of(e)?;
        let v = self.expr(e)?;
        Ok(coerce(v, &t, want))
    }

    /// The Go type inty recorded for the expression at `span`.
    fn go_type_at(&mut self, span: Span) -> Result<GoType> {
        let t = self.raw_type(span)?;
        self.tm.map(self.state, &t, span)
    }

    fn to_str(&mut self, v: String, t: &GoType, span: Span) -> Result<String> {
        Ok(match t {
            GoType::Str => v,
            GoType::Float => format!("intyNumStr({})", v),
            GoType::Int => format!("strconv.Itoa({})", v),
            GoType::Bool => format!("intyBoolStr({})", v),
            GoType::Array(elem) => {
                let f = self.str_func(elem, span)?;
                format!("intyJoin({}, \",\", {})", v, f)
            }
            _ => return Err(unsupported("string conversion of this type", span)),
        })
    }

    /// A Go func value converting `t` to a string (for `join`).
    fn str_func(&mut self, t: &GoType, span: Span) -> Result<String> {
        Ok(match t {
            GoType::Str => "func(s string) string { return s }".into(),
            GoType::Float => "intyNumStr".into(),
            GoType::Int => "strconv.Itoa".into(),
            GoType::Bool => "intyBoolStr".into(),
            _ => return Err(unsupported("join over elements of this type", span)),
        })
    }

    fn expr(&mut self, e: &Expr) -> Result<String> {
        if let Some(n) = const_num(e) {
            if crate::types::is_int(n) && self.type_of(e).ok() == Some(GoType::Int) {
                return Ok(int_lit(n));
            }
            return Ok(num_lit(n));
        }
        match e {
            Expr::Lit { value, span } => match value {
                Literal::Number(n) => Ok(num_lit(*n)),
                Literal::String(s) => Ok(go_string_lit(s)),
                Literal::Boolean(b) => Ok(b.to_string()),
                Literal::Null | Literal::Undefined => Ok("nil".into()),
                Literal::Regex { .. } => Err(unsupported("regular expression", *span)),
            },
            Expr::Ident { name, span } => {
                if let Some((go, _)) = self.ident(name, *span)? {
                    return Ok(go);
                }
                match name.as_str() {
                    "NaN" => Ok("math.NaN()".into()),
                    "Infinity" => Ok("math.Inf(1)".into()),
                    "undefined" => Ok("nil".into()),
                    _ => Ok(mangle(name)),
                }
            }
            Expr::This { span } => Err(unsupported("`this`", *span)),
            Expr::Array { elements, span } => {
                let elem = match self.type_of(e)? {
                    GoType::Array(el) => *el,
                    _ => return Err(unsupported("array literal of non-array type", *span)),
                };
                let mut items = Vec::new();
                for el in elements {
                    match el {
                        None => return Err(unsupported("array hole", *span)),
                        Some(Expr::Spread { span, .. }) => {
                            return Err(unsupported("array spread", *span))
                        }
                        Some(x) => items.push(self.expr_as(x, &elem)?),
                    }
                }
                let t = self.tm.render(&elem);
                if items.len() > 2 {
                    let pad = self.pad();
                    let inner: Vec<String> =
                        items.iter().map(|i| format!("{pad}\t{i},\n")).collect();
                    Ok(format!("&[]{}{{\n{}{}}}", t, inner.concat(), pad))
                } else {
                    Ok(format!("&[]{}{{{}}}", t, items.join(", ")))
                }
            }
            Expr::Object { properties, span } => {
                let idx = match self.type_of(e)? {
                    GoType::Struct(i) => i,
                    _ => return Err(unsupported("object literal of this type", *span)),
                };
                let mut fields = Vec::new();
                for p in properties {
                    match p {
                        PropDef::Property { key, value, .. } => {
                            let k = match key {
                                PropKey::Ident(s) | PropKey::String(s) => s.clone(),
                                PropKey::Number(n) => format!("{}", n),
                            };
                            let (_, go, ft) = self.tm.field(idx, &k).cloned().ok_or_else(|| {
                                unsupported("object field missing from its type", *span)
                            })?;
                            let v = self.expr_as(value, &ft)?;
                            fields.push(format!("{}: {}", go, v));
                        }
                        PropDef::Method {
                            key,
                            params,
                            body,
                            span,
                            ..
                        } => {
                            let k = match key {
                                PropKey::Ident(s) | PropKey::String(s) => s.clone(),
                                PropKey::Number(n) => format!("{}", n),
                            };
                            let go =
                                self.tm.field(idx, &k).map(|f| f.1.clone()).ok_or_else(|| {
                                    unsupported("method missing from its type", *span)
                                })?;
                            let f = self.func_literal(params, body, *span)?;
                            fields.push(format!("{}: {}", go, f));
                        }
                        PropDef::Getter { span, .. } | PropDef::Setter { span, .. } => {
                            return Err(unsupported("getter/setter", *span))
                        }
                        PropDef::Spread { span, .. } => {
                            return Err(unsupported("object spread", *span))
                        }
                    }
                }
                let name = self.tm.structs[idx].name.clone();
                Ok(format!("&{}{{{}}}", name, fields.join(", ")))
            }
            Expr::Function {
                name,
                params,
                body,
                span,
                ..
            } => {
                if name.is_some() {
                    return Err(unsupported("named function expression", *span));
                }
                self.func_literal(params, body, *span)
            }
            Expr::Member {
                object,
                property,
                span,
            } => self.member(object, property, *span),
            Expr::ComputedMember {
                object,
                property,
                span,
            } => match self.type_of(object)? {
                GoType::Array(_) => {
                    let a = self.expr(object)?;
                    let i = self.index(property)?;
                    Ok(format!("(*{})[{}]", a, i))
                }
                GoType::Str => {
                    let s = self.expr(object)?;
                    let i = self.index(property)?;
                    Ok(format!("string({}[{}])", s, i))
                }
                _ => Err(unsupported("computed member access on this type", *span)),
            },
            Expr::Call {
                callee,
                arguments,
                span,
                ..
            } => {
                if let Some(v) = self.array_fill(callee, arguments, *span)? {
                    return Ok(v);
                }
                match self.fused(e)? {
                    Some(v) => Ok(v),
                    None => self.call(callee, arguments, *span, false),
                }
            }
            Expr::Unary { op, argument, span } => self.unary(*op, argument, *span, e),
            Expr::Binary {
                op,
                left,
                right,
                span,
            } => self.binary(*op, left, right, *span),
            Expr::Assign { .. } => {
                // Assignment used as a value: run it, then read it back.
                let t = self.type_of(e)?;
                let Expr::Assign { left, .. } = e else {
                    unreachable!()
                };
                if !is_pure_place(left) {
                    return Err(unsupported(
                        "assignment expression with side-effecting target",
                        e.span(),
                    ));
                }
                let s = self.simple_stmt(e)?;
                let p = self.place(left)?;
                Ok(format!(
                    "func() {} {{ {}; return {} }}()",
                    self.tm.render(&t),
                    s,
                    p
                ))
            }
            Expr::Conditional {
                test,
                consequent,
                alternate,
                ..
            } => {
                let t = self.type_of(e)?;
                let c = self.cond(test)?;
                let a = self.expr_as(consequent, &t)?;
                let b = self.expr_as(alternate, &t)?;
                Ok(format!(
                    "func() {} {{\n{p}\tif {} {{\n{p}\t\treturn {}\n{p}\t}}\n{p}\treturn {}\n{p}}}()",
                    self.tm.render(&t),
                    c,
                    a,
                    b,
                    p = self.pad()
                ))
            }
            Expr::TemplateLiteral {
                quasis,
                expressions,
                span,
            } => {
                let mut parts = Vec::new();
                for (i, q) in quasis.iter().enumerate() {
                    if !q.is_empty() {
                        parts.push(go_string_lit(q));
                    }
                    if let Some(x) = expressions.get(i) {
                        let t = self.type_of(x)?;
                        let v = self.expr(x)?;
                        parts.push(self.to_str(v, &t, *span)?);
                    }
                }
                if parts.is_empty() {
                    Ok("\"\"".into())
                } else {
                    Ok(format!("({})", parts.join(" + ")))
                }
            }
            Expr::Tuple { span, .. } => Err(unsupported("tuple", *span)),
            Expr::New { span, .. } => Err(unsupported("`new`", *span)),
            Expr::NewTarget { span } => Err(unsupported("new.target", *span)),
            Expr::NullishCoalesce { span, .. } => Err(unsupported("`??`", *span)),
            Expr::OptionalChain { span, .. } => Err(unsupported("optional chaining", *span)),
            Expr::Spread { span, .. } => Err(unsupported("spread", *span)),
            Expr::RestArray { span, .. } | Expr::RestRow { span, .. } => {
                Err(unsupported("destructuring rest pattern", *span))
            }
            Expr::Sequence { span, .. } => Err(unsupported("comma operator", *span)),
        }
    }

    fn member(&mut self, object: &Expr, property: &str, span: Span) -> Result<String> {
        if let Some(module) = self.node_item(object) {
            return match module.member(property) {
                Some(NodeItem::Argv) => Ok("intyArgv".into()),
                _ => Err(unsupported(
                    format!("Node built-in `.{}` used as a value", property),
                    span,
                )),
            };
        }
        match self.type_of(object)? {
            GoType::Array(_) if property == "length" => {
                let a = self.expr(object)?;
                let want = self.go_type_at(span)?;
                Ok(coerce(format!("len(*{})", a), &GoType::Int, &want))
            }
            GoType::Str if property == "length" => {
                let s = self.expr(object)?;
                let want = self.go_type_at(span)?;
                Ok(coerce(format!("len({})", s), &GoType::Int, &want))
            }
            GoType::Struct(idx) => {
                let go = self
                    .tm
                    .field(idx, property)
                    .map(|f| f.1.clone())
                    .ok_or_else(|| unsupported(format!("property `{}`", property), span))?;
                let o = self.expr(object)?;
                Ok(format!("{}.{}", o, go))
            }
            _ => Err(unsupported(
                format!("property `.{}` on this type", property),
                span,
            )),
        }
    }

    fn unary(&mut self, op: UnaryOp, arg: &Expr, span: Span, whole: &Expr) -> Result<String> {
        let t = self.type_of(arg)?;
        match op {
            UnaryOp::Neg | UnaryOp::Pos if is_num(&t) => {
                let want = self.go_type_at(span)?;
                let v = self.num_as(arg, &want)?;
                Ok(if op == UnaryOp::Neg {
                    format!("(-{})", v)
                } else {
                    v
                })
            }
            UnaryOp::Not => {
                let v = self.expr(arg)?;
                let c = self.truthy(v, &t, span)?;
                Ok(format!("(!{})", c))
            }
            UnaryOp::BitNot => {
                let v = self.expr(arg)?;
                let want = self.go_type_at(span)?;
                Ok(coerce(
                    format!("int(^{})", to_i32(v, &t)),
                    &GoType::Int,
                    &want,
                ))
            }
            UnaryOp::Typeof if matches!(arg, Expr::Ident { .. }) => Ok(go_string_lit(match t {
                GoType::Float | GoType::Int => "number",
                GoType::Str => "string",
                GoType::Bool => "boolean",
                GoType::Func(..) => "function",
                GoType::Unit => "undefined",
                _ => "object",
            })),
            UnaryOp::PreInc | UnaryOp::PreDec | UnaryOp::PostInc | UnaryOp::PostDec => {
                if !is_pure_place(arg) {
                    return Err(unsupported("update of a side-effecting place", span));
                }
                let p = self.place(arg)?;
                let o = if matches!(op, UnaryOp::PreInc | UnaryOp::PostInc) {
                    "++"
                } else {
                    "--"
                };
                let _ = whole;
                let rt = self.tm.render(&t);
                if matches!(op, UnaryOp::PostInc | UnaryOp::PostDec) {
                    Ok(format!("func() {rt} {{ t := {p}; {p}{o}; return t }}()"))
                } else {
                    Ok(format!("func() {rt} {{ {p}{o}; return {p} }}()"))
                }
            }
            _ => Err(unsupported(format!("unary `{:?}` on this type", op), span)),
        }
    }

    fn binary(&mut self, op: BinOp, left: &Expr, right: &Expr, span: Span) -> Result<String> {
        let lt = self.type_of(left)?;
        let rt = self.type_of(right)?;
        let is_nullish = |e: &Expr| {
            matches!(
                e,
                Expr::Lit {
                    value: Literal::Null | Literal::Undefined,
                    ..
                }
            ) || matches!(e, Expr::Ident { name, .. } if name == "undefined")
        };
        // Equality against null/undefined on a nullable value.
        if matches!(
            op,
            BinOp::EqEq | BinOp::EqEqEq | BinOp::NotEq | BinOp::NotEqEq
        ) {
            let neg = matches!(op, BinOp::NotEq | BinOp::NotEqEq);
            let cmp = if neg { "!=" } else { "==" };
            if is_nullish(right) && lt.is_nullable() {
                return Ok(format!("({} {} nil)", self.expr(left)?, cmp));
            }
            if is_nullish(left) && rt.is_nullable() {
                return Ok(format!("({} {} nil)", self.expr(right)?, cmp));
            }
        }
        let a = self.expr(left)?;
        let b = self.expr(right)?;
        let num = is_num(&lt) && is_num(&rt);
        // Arithmetic happens in the result's type (an `Int` operand of a
        // `Number` operation becomes a float64); a comparison in `Int` only
        // when both sides are.
        let whole = if num {
            self.go_type_at(span)?
        } else {
            GoType::Unit
        };
        let both_int = lt == GoType::Int && rt == GoType::Int;
        let cmp_t = if both_int { GoType::Int } else { GoType::Float };
        let (fa, fb) = (
            coerce(a.clone(), &lt, &GoType::Float),
            coerce(b.clone(), &rt, &GoType::Float),
        );
        let (wa, wb) = (
            coerce(a.clone(), &lt, &whole),
            coerce(b.clone(), &rt, &whole),
        );
        let (ca, cb) = (
            coerce(a.clone(), &lt, &cmp_t),
            coerce(b.clone(), &rt, &cmp_t),
        );
        let int_result = |s: String, whole: &GoType| coerce(s, &GoType::Int, whole);
        Ok(match op {
            BinOp::Add if lt == GoType::Str || rt == GoType::Str => {
                let a = self.to_str(a, &lt, span)?;
                let b = self.to_str(b, &rt, span)?;
                format!("({} + {})", a, b)
            }
            BinOp::Add if num => format!("({} + {})", wa, wb),
            BinOp::Sub if num => format!("({} - {})", wa, wb),
            BinOp::Mul if num && whole == GoType::Int => format!("intyIMul({}, {})", wa, wb),
            BinOp::Mul if num => format!("({} * {})", wa, wb),
            BinOp::Div if num && const_num(right) == Some(0.0) => format!("({} / intyZero)", fa),
            BinOp::Div if num => format!("({} / {})", fa, fb),
            // Go's `%` truncates like JS's; an Int remainder by zero traps
            // (JS gives NaN, which isn't an Int).
            BinOp::Mod if num && whole == GoType::Int => format!("({} % {})", wa, wb),
            BinOp::Mod if num => format!("intyMod({}, {})", wa, wb),
            BinOp::Pow if num => format!("intyPow({}, {})", fa, fb),
            BinOp::Lt | BinOp::Gt | BinOp::LtEq | BinOp::GtEq
                if num || (lt == GoType::Str && rt == GoType::Str) =>
            {
                let o = match op {
                    BinOp::Lt => "<",
                    BinOp::Gt => ">",
                    BinOp::LtEq => "<=",
                    _ => ">=",
                };
                if num {
                    format!("({} {} {})", ca, o, cb)
                } else {
                    format!("({} {} {})", a, o, b)
                }
            }
            BinOp::EqEq | BinOp::EqEqEq | BinOp::NotEq | BinOp::NotEqEq if num || lt == rt => {
                let o = if matches!(op, BinOp::EqEq | BinOp::EqEqEq) {
                    "=="
                } else {
                    "!="
                };
                match lt {
                    GoType::Func(..) => {
                        return Err(unsupported("comparing functions", span));
                    }
                    _ if num => format!("({} {} {})", ca, o, cb),
                    _ => format!("({} {} {})", a, o, b),
                }
            }
            BinOp::And | BinOp::Or if lt == GoType::Bool && rt == GoType::Bool => {
                let o = if op == BinOp::And { "&&" } else { "||" };
                format!("({} {} {})", a, o, b)
            }
            // The bitwise operators work on 32-bit integers and give one.
            BinOp::BitAnd | BinOp::BitOr | BinOp::BitXor if num => {
                let o = match op {
                    BinOp::BitAnd => "&",
                    BinOp::BitOr => "|",
                    _ => "^",
                };
                int_result(
                    format!("int({} {} {})", to_i32(a, &lt), o, to_i32(b, &rt)),
                    &whole,
                )
            }
            BinOp::LShift if num => int_result(
                format!("int({} << ({} & 31))", to_i32(a, &lt), to_u32(b, &rt)),
                &whole,
            ),
            BinOp::RShift if num => int_result(
                format!("int({} >> ({} & 31))", to_i32(a, &lt), to_u32(b, &rt)),
                &whole,
            ),
            BinOp::URShift if num => int_result(
                format!("int({} >> ({} & 31))", to_u32(a, &lt), to_u32(b, &rt)),
                &whole,
            ),
            _ => {
                return Err(unsupported(
                    format!(
                        "operator `{:?}` on {} and {}",
                        op,
                        self.tm.render(&lt),
                        self.tm.render(&rt)
                    ),
                    span,
                ))
            }
        })
    }

    /// Emit a call. `stmt` is true in statement position, where a call
    /// returning `undefined` is allowed.
    fn call(&mut self, callee: &Expr, args: &[Expr], span: Span, stmt: bool) -> Result<String> {
        let result = self
            .raw_type(span)
            .and_then(|t| self.tm.map(self.state, &t, span));
        if !stmt && matches!(result, Ok(GoType::Unit)) {
            return Err(unsupported(
                "using the result of a call that returns undefined",
                span,
            ));
        }
        if let Some(s) = self.node_call(callee, args, span, stmt)? {
            return Ok(s);
        }
        if let Expr::Member {
            object, property, ..
        } = callee
        {
            if let Expr::Ident { name, .. } = &**object {
                if let Some(s) = self.builtin_static(name, property, args, span, stmt)? {
                    return Ok(s);
                }
            }
            match self.type_of(object)? {
                GoType::Array(elem) => {
                    return self.array_method(object, &elem, property, args, span, stmt)
                }
                GoType::Str => return self.string_method(object, property, args, span),
                GoType::Struct(_) => {} // a function-valued field: ordinary call below
                _ => {
                    return Err(unsupported(
                        format!("method `.{}` on this type", property),
                        span,
                    ))
                }
            }
        }
        if let Expr::Ident { name, .. } = callee {
            match name.as_str() {
                "String" if args.len() == 1 => {
                    let t = self.type_of(&args[0])?;
                    let v = self.expr(&args[0])?;
                    return self.to_str(v, &t, span);
                }
                "isNaN" if args.len() == 1 => {
                    let v = self.num_as(&args[0], &GoType::Float)?;
                    return Ok(format!("math.IsNaN({})", v));
                }
                _ => {}
            }
        }
        let f = self.expr(callee)?;
        let params = match self.type_of(callee)? {
            GoType::Func(ps, _) => ps,
            _ => return Err(unsupported("call of a non-function", span)),
        };
        if params.len() != args.len() {
            return Err(unsupported("call with omitted optional arguments", span));
        }
        let mut vs = Vec::new();
        for (a, p) in args.iter().zip(&params) {
            vs.push(self.expr_as(a, p)?);
        }
        let f = if matches!(callee, Expr::Ident { .. } | Expr::Member { .. }) {
            f
        } else {
            format!("({})", f)
        };
        Ok(format!("{}({})", f, vs.join(", ")))
    }

    /// A call of a Node built-in: `readFileSync(path, "utf8")`,
    /// `process.stdout.write(s)`, `process.exit(code)`, ….
    fn node_call(
        &mut self,
        callee: &Expr,
        args: &[Expr],
        span: Span,
        stmt: bool,
    ) -> Result<Option<String>> {
        let (item, write) = match callee {
            Expr::Member {
                object, property, ..
            } if property == "write" => match self.node_item(object) {
                Some(s @ (NodeItem::Stdout | NodeItem::Stderr)) => (s, true),
                _ => match self.node_item(callee) {
                    Some(item) => (item, false),
                    None => return Ok(None),
                },
            },
            _ => match self.node_item(callee) {
                Some(item) => (item, false),
                None => return Ok(None),
            },
        };
        let mut vs = Vec::new();
        for a in args {
            let t = self.type_of(a)?;
            vs.push(if is_num(&t) {
                self.num_as(a, &GoType::Float)?
            } else {
                self.expr(a)?
            });
        }
        let helper = match (item, write, vs.len()) {
            (NodeItem::Stdout, true, 1) => "intyStdoutWrite",
            (NodeItem::Stderr, true, 1) => "intyStderrWrite",
            (NodeItem::ReadFileSync, _, 2) => "intyReadFileSync",
            (NodeItem::WriteFileSync, _, 2) => "intyWriteFileSync",
            (NodeItem::AppendFileSync, _, 2) => "intyAppendFileSync",
            (NodeItem::ExistsSync, _, 1) => "intyExistsSync",
            (NodeItem::Exit, _, 1) => {
                if !stmt {
                    return Err(unsupported("using the result of process.exit", span));
                }
                "intyExit"
            }
            _ => return Err(unsupported("this use of a Node built-in", span)),
        };
        Ok(Some(format!("{}({})", helper, vs.join(", "))))
    }

    /// `Math.*`, `console.*`, `String.fromCharCode`, `Number.isInteger`.
    fn builtin_static(
        &mut self,
        object: &str,
        property: &str,
        args: &[Expr],
        span: Span,
        stmt: bool,
    ) -> Result<Option<String>> {
        let mut vals = Vec::new();
        // (The built-ins take doubles.)
        let arg = |e: &mut Self, vals: &mut Vec<String>| -> Result<()> {
            for a in args {
                vals.push(e.num_as(a, &GoType::Float)?);
            }
            Ok(())
        };
        Ok(Some(match (object, property) {
            ("console", "log" | "error" | "warn") => {
                if !stmt {
                    return Err(unsupported("using the result of console.log", span));
                }
                let [a] = args else {
                    return Err(unsupported("console.log with several arguments", span));
                };
                let t = self.type_of(a)?;
                if matches!(t, GoType::Array(_)) {
                    // Node's console.log formats arrays specially.
                    return Err(unsupported(
                        "console.log of an array (use .join())",
                        a.span(),
                    ));
                }
                let v = self.expr(a)?;
                // console.log formats numbers with util.inspect, which
                // (unlike String(x)) keeps the sign of -0. (An `Int` has
                // no -0.)
                let s = if t == GoType::Float {
                    format!("intyInspectNum({})", v)
                } else {
                    self.to_str(v, &t, a.span())?
                };
                if property == "log" {
                    format!("intyLog({})", s)
                } else {
                    format!("intyLogErr({})", s)
                }
            }
            // Polymorphic in `Num`: computed in the result's type.
            ("Math", f @ ("abs" | "min" | "max")) => {
                let want = self.go_type_at(span)?;
                let want = if is_num(&want) { want } else { GoType::Float };
                for a in args {
                    vals.push(self.num_as(a, &want)?);
                }
                match (f, &want) {
                    ("abs", GoType::Int) => format!("intyAbsInt({})", vals.join(", ")),
                    ("abs", _) => format!("math.Abs({})", vals.join(", ")),
                    // Go 1.21 builtins: NaN-propagating, -0 < +0 — exactly
                    // JS semantics, and compiled inline (math.Min is a call).
                    _ => format!("{}({})", f, vals.join(", ")),
                }
            }
            // To an `Int`, checked.
            ("Math", f @ ("floor" | "ceil" | "round" | "trunc"))
                if self.go_type_at(span)? == GoType::Int =>
            {
                arg(self, &mut vals)?;
                let go = match f {
                    "floor" => "intyFloorInt",
                    "ceil" => "intyCeilInt",
                    "round" => "intyRoundInt",
                    _ => "intyTruncInt",
                };
                format!("{}({})", go, vals.join(", "))
            }
            ("Math", f) => {
                arg(self, &mut vals)?;
                let go = match f {
                    "abs" => "math.Abs",
                    "floor" => "math.Floor",
                    "ceil" => "math.Ceil",
                    "round" => "intyRound",
                    "trunc" => "math.Trunc",
                    "sign" => "intySign",
                    "sqrt" => "math.Sqrt",
                    "cbrt" => "math.Cbrt",
                    "pow" => "intyPow",
                    "hypot" => "math.Hypot",
                    "log" => "math.Log",
                    "log2" => "math.Log2",
                    "log10" => "math.Log10",
                    "exp" => "math.Exp",
                    "expm1" => "math.Expm1",
                    "log1p" => "math.Log1p",
                    "sin" => "math.Sin",
                    "cos" => "math.Cos",
                    "tan" => "math.Tan",
                    "asin" => "math.Asin",
                    "acos" => "math.Acos",
                    "atan" => "math.Atan",
                    "atan2" => "math.Atan2",
                    "sinh" => "math.Sinh",
                    "cosh" => "math.Cosh",
                    "tanh" => "math.Tanh",
                    "random" => "rand.Float64",
                    "imul" => "intyImul",
                    "fround" => "intyFround",
                    "clz32" => "intyClz32",
                    _ => return Err(unsupported(format!("Math.{}", f), span)),
                };
                format!("{}({})", go, vals.join(", "))
            }
            ("performance", "now") if args.is_empty() => "intyNow()".into(),
            ("String", "fromCharCode") if args.len() == 1 => {
                arg(self, &mut vals)?;
                format!("intyFromCharCode({})", vals[0])
            }
            ("Number", "isInteger") if args.len() == 1 => {
                arg(self, &mut vals)?;
                format!("intyIsInteger({})", vals[0])
            }
            _ => return Ok(None),
        }))
    }

    fn array_method(
        &mut self,
        object: &Expr,
        elem: &GoType,
        method: &str,
        args: &[Expr],
        span: Span,
        stmt: bool,
    ) -> Result<String> {
        let a = self.expr(object)?;
        let et = self.tm.render(elem);
        let n = args.len();
        if method == "splice" && n >= 1 {
            // splice(start, deleteCount?, ...items). In statement position
            // the removed elements aren't collected.
            let start = self.num_as(&args[0], &GoType::Float)?;
            let del = match args.get(1) {
                Some(d) => self.num_as(d, &GoType::Float)?,
                None => "math.Inf(1)".into(),
            };
            let mut call = format!(
                "{}({}, {}, {}",
                if stmt { "intySpliceStmt" } else { "intySplice" },
                a,
                start,
                del
            );
            for x in args.iter().skip(2) {
                call.push_str(", ");
                call.push_str(&self.expr_as(x, elem)?);
            }
            call.push(')');
            return Ok(call);
        }
        let mut vs = Vec::new();
        for x in args {
            vs.push(self.expr_as(x, elem)?);
        }
        Ok(match (method, n) {
            ("push", 1) => format!("intyPush({}, {})", a, vs[0]),
            ("pop", 0) => format!("intyPop({})", a),
            ("unshift", 1) => format!("intyUnshift({}, {})", a, vs[0]),
            ("indexOf", 1) => format!("intyIndexOf({}, {})", a, vs[0]),
            ("includes", 1) => format!("intyIncludes({}, {})", a, vs[0]),
            ("fill", 1) => format!("intyFill({}, {})", a, vs[0]),
            ("reverse", 0) => format!("intyReverse({})", a),
            ("concat", 1) => {
                let b = self.expr(&args[0])?;
                format!("intyConcat({}, {})", a, b)
            }
            ("slice", _) if n <= 2 => {
                let mut ix = Vec::new();
                for x in args {
                    ix.push(self.num_as(x, &GoType::Float)?);
                }
                let start = ix.first().cloned().unwrap_or_else(|| "0.0".into());
                let end = ix.get(1).cloned().unwrap_or_else(|| "math.Inf(1)".into());
                format!("intySlice({}, {}, {})", a, start, end)
            }
            ("join", _) if n <= 1 => {
                let sep = match args.first() {
                    Some(s) => self.expr(s)?,
                    None => "\",\"".into(),
                };
                let f = self.str_func(elem, span)?;
                format!("intyJoin({}, {}, {})", a, sep, f)
            }
            ("map" | "filter" | "forEach" | "some" | "every" | "findIndex", 1) => {
                let f = self.expr(&args[0])?;
                let helper = match method {
                    "map" => "intyMap",
                    "filter" => "intyFilter",
                    "forEach" => "intyForEach",
                    "some" => "intySome",
                    "every" => "intyEvery",
                    _ => "intyFindIndex",
                };
                format!("{}({}, {})", helper, a, f)
            }
            ("reduce", 2) => {
                let f = self.expr(&args[0])?;
                // The accumulator has the result's type (`0` for a sum of
                // doubles is a double).
                let acc_t = self.go_type_at(span)?;
                let acc = self.expr_as(&args[1], &acc_t)?;
                format!("intyReduce({}, {}, {})", a, f, acc)
            }
            _ => {
                let _ = et;
                return Err(unsupported(
                    format!("Array method `.{}`/{}", method, n),
                    span,
                ));
            }
        })
    }

    fn string_method(
        &mut self,
        object: &Expr,
        method: &str,
        args: &[Expr],
        span: Span,
    ) -> Result<String> {
        let s = self.expr(object)?;
        // Numeric arguments as doubles (the helpers' JS semantics), except
        // where every bound is an `Int`: then the `Int` fast paths.
        let mut types = Vec::new();
        for x in args {
            types.push(self.type_of(x)?);
        }
        let all_int = !args.is_empty() && types.iter().all(|t| *t == GoType::Int);
        let mut vs = Vec::new();
        for (x, t) in args.iter().zip(&types) {
            vs.push(if is_num(t) {
                self.num_as(x, &GoType::Float)?
            } else {
                self.expr(x)?
            });
        }
        let want = self.go_type_at(span)?;
        if all_int && matches!(method, "slice" | "substring" | "charCodeAt") {
            let mut is = Vec::new();
            for x in args {
                is.push(self.expr(x)?);
            }
            let f = if method == "slice" {
                "intyStrSliceI"
            } else {
                "intyStrSubstringI"
            };
            return Ok(match (method, is.as_slice()) {
                ("charCodeAt", [i]) => coerce(format!("int({}[{}])", s, i), &GoType::Int, &want),
                (_, [a]) => format!("{}({}, {}, len({}))", f, s, a, s),
                (_, [a, b]) => format!("{}({}, {}, {})", f, s, a, b),
                _ => return Err(unsupported(format!("String method `.{}`", method), span)),
            });
        }
        let int_res = |v: String| coerce(v, &GoType::Int, &want);
        Ok(match (method, vs.as_slice()) {
            ("charCodeAt", [i]) => int_res(format!("int({}[int({})])", s, i)),
            ("indexOf", [x]) => int_res(format!("intyStrIndexOf({}, {})", s, x)),
            ("includes", [x]) => format!("strings.Contains({}, {})", s, x),
            ("startsWith", [x]) => format!("strings.HasPrefix({}, {})", s, x),
            ("startsWith", [x, pos]) => format!("intyStartsWithAt({}, {}, {})", s, x, pos),
            ("endsWith", [x]) => format!("strings.HasSuffix({}, {})", s, x),
            ("toUpperCase", []) => format!("strings.ToUpper({})", s),
            ("toLowerCase", []) => format!("strings.ToLower({})", s),
            ("trim", []) => format!("strings.TrimSpace({})", s),
            ("repeat", [n]) => format!("strings.Repeat({}, int({}))", s, n),
            ("slice", [a]) => format!("intyStrSlice({}, {}, math.Inf(1))", s, a),
            ("slice", [a, b]) => format!("intyStrSlice({}, {}, {})", s, a, b),
            ("substring", [a]) => format!("intyStrSubstring({}, {}, math.Inf(1))", s, a),
            ("substring", [a, b]) => format!("intyStrSubstring({}, {}, {})", s, a, b),
            ("indexOf", [x, from]) => {
                int_res(format!("intyStrIndexOfFrom({}, {}, {})", s, x, from))
            }
            ("lastIndexOf", [x]) => int_res(format!("strings.LastIndex({}, {})", s, x)),
            ("charAt", [i]) => format!("intyCharAt({}, {})", s, i),
            ("trimStart", []) => format!("strings.TrimLeftFunc({}, unicode.IsSpace)", s),
            ("trimEnd", []) => format!("strings.TrimRightFunc({}, unicode.IsSpace)", s),
            ("split", [sep]) => format!("intySplit({}, {}, math.Inf(1))", s, sep),
            ("split", [sep, limit]) => format!("intySplit({}, {}, {})", s, sep, limit),
            ("replace", [pat, rep]) => format!("intyReplace({}, {}, {}, 1)", s, pat, rep),
            ("replaceAll", [pat, rep]) => format!("intyReplace({}, {}, {}, -1)", s, pat, rep),
            ("padStart", [n]) => format!("intyPad({}, {}, \" \", true)", s, n),
            ("padStart", [n, pad]) => format!("intyPad({}, {}, {}, true)", s, n, pad),
            ("padEnd", [n]) => format!("intyPad({}, {}, \" \", false)", s, n),
            ("padEnd", [n, pad]) => format!("intyPad({}, {}, {}, false)", s, n, pad),
            ("concat", [x]) => format!("({} + {})", s, x),
            _ => return Err(unsupported(format!("String method `.{}`", method), span)),
        })
    }

    /// `new Array(n).fill(v)` / `Array(n).fill(v)`: one allocation of the
    /// final size (building it by `push` copies it as it grows).
    fn array_fill(&mut self, callee: &Expr, args: &[Expr], span: Span) -> Result<Option<String>> {
        let (
            Expr::Member {
                object, property, ..
            },
            [value],
        ) = (callee, args)
        else {
            return Ok(None);
        };
        if property != "fill" {
            return Ok(None);
        }
        let len = match &**object {
            Expr::New {
                callee, arguments, ..
            }
            | Expr::Call {
                callee, arguments, ..
            } => match (&**callee, arguments.as_slice()) {
                (Expr::Ident { name, .. }, [n])
                    if name == "Array" && self.lookup(name).is_none() =>
                {
                    n
                }
                _ => return Ok(None),
            },
            _ => return Ok(None),
        };
        let GoType::Array(elem) = self.go_type_at(span)? else {
            return Ok(None);
        };
        let n = self.num_as(len, &GoType::Int)?;
        let v = self.expr_as(value, &elem)?;
        Ok(Some(format!("intyFilled({}, {})", n, v)))
    }

    // ---- array pipelines ----------------------------------------------------
    //
    // `xs.map(f).filter(g).reduce(h, 0)` would build two throwaway arrays;
    // allocating, zeroing and collecting them is most of such a program's
    // time. When every callback is pure, the chain is one loop over `xs`
    // instead (fusion, as in Rust's iterators or Haskell's stream fusion):
    // the only difference is that the callbacks' calls interleave, which a
    // pure callback can't observe. A `const` holding an intermediate array
    // fuses too, when its one use is the next statement's pipeline.

    /// `e` as a fused loop, if it's a pipeline of at least two steps.
    fn fused(&mut self, e: &Expr) -> Result<Option<String>> {
        let Some(p) = self.pipeline(e) else {
            return Ok(None);
        };
        self.emit_pipeline(&p, e.span()).map(Some)
    }

    /// Recognise `e` as a pipeline whose callbacks are all pure: its steps
    /// (expanding a deferred `const` source) and what consumes them.
    fn pipeline(&mut self, e: &Expr) -> Option<Pipeline> {
        let p = self.pipeline_parts(e)?;
        let steps = p.stages.len() + usize::from(!matches!(p.sink, Sink::Collect(_)));
        (steps >= 2).then_some(p)
    }

    /// [`Self::pipeline`] without the two-step minimum (a deferred `const`
    /// is one step of a longer chain).
    fn pipeline_parts(&mut self, e: &Expr) -> Option<Pipeline> {
        let (sink, mut object) = match e {
            Expr::Call {
                callee, arguments, ..
            } => match &**callee {
                Expr::Member {
                    object, property, ..
                } => {
                    let sink = match (property.as_str(), arguments.as_slice()) {
                        ("reduce", [f, init]) => Sink::Reduce(f.clone(), init.clone()),
                        ("forEach", [f]) => Sink::ForEach(f.clone()),
                        ("some", [f]) => Sink::Some(f.clone()),
                        ("every", [f]) => Sink::Every(f.clone()),
                        ("findIndex", [f]) => Sink::FindIndex(f.clone()),
                        ("map", [f]) => Sink::Collect(Some(Stage::Map(f.clone()))),
                        ("filter", [f]) => Sink::Collect(Some(Stage::Filter(f.clone()))),
                        _ => return None,
                    };
                    (sink, (**object).clone())
                }
                _ => return None,
            },
            _ => return None,
        };
        let mut stages: Vec<Stage> = Vec::new();
        if let Sink::Collect(Some(st)) = &sink {
            stages.push(st.clone());
        }
        loop {
            match &object {
                Expr::Call {
                    callee, arguments, ..
                } => match (&**callee, arguments.as_slice()) {
                    (
                        Expr::Member {
                            object: inner,
                            property,
                            ..
                        },
                        [f],
                    ) if property == "map" || property == "filter" => {
                        let st = if property == "map" {
                            Stage::Map(f.clone())
                        } else {
                            Stage::Filter(f.clone())
                        };
                        stages.insert(0, st);
                        object = (**inner).clone();
                    }
                    _ => break,
                },
                Expr::Ident { name, .. } if self.deferred.contains_key(name) => {
                    let init = self.deferred.get(name).cloned().expect("checked");
                    let inner = self.pipeline_parts(&init)?;
                    let Sink::Collect(_) = inner.sink else {
                        return None;
                    };
                    let mut all = inner.stages;
                    all.append(&mut stages);
                    stages = all;
                    object = inner.source;
                    break;
                }
                _ => break,
            }
        }
        // Only arrays: the source must be one.
        if !matches!(self.type_of(&object), Ok(GoType::Array(_))) {
            return None;
        }
        let callbacks: Vec<Expr> = stages
            .iter()
            .map(|s| match s {
                Stage::Map(f) | Stage::Filter(f) => f.clone(),
            })
            .chain(sink.callback().cloned())
            .collect();
        for f in &callbacks {
            if !self.pure_callback(f) {
                return None;
            }
        }
        Some(Pipeline {
            source: object,
            stages,
            sink,
        })
    }

    /// The Go code of a fused pipeline: one loop in a function literal
    /// called in place (Go inlines both it and the callbacks bound in it).
    fn emit_pipeline(&mut self, p: &Pipeline, span: Span) -> Result<String> {
        let pad = self.pad();
        let mut body = String::new();
        // (The callbacks are bound one level in.)
        self.indent += 1;
        let mut fs = Vec::new();
        let mut sink_f = None;
        let r = (|| -> Result<()> {
            for st in &p.stages {
                let f = match st {
                    Stage::Map(f) | Stage::Filter(f) => f,
                };
                fs.push(self.expr(f)?);
            }
            if let Some(f) = p.sink.callback() {
                sink_f = Some(self.expr(f)?);
            }
            Ok(())
        })();
        self.indent -= 1;
        r?;
        let src = self.expr(&p.source)?;
        let result = self.go_type_at(span)?;
        let n = self.fresh("P");
        for (i, f) in fs.iter().enumerate() {
            body.push_str(&format!("{pad}\t{n}f{i} := {f}\n"));
        }
        if let Some(f) = &sink_f {
            body.push_str(&format!("{pad}\t{n}s := {f}\n"));
        }
        body.push_str(&format!("{pad}\t{n}src := {src}\n"));
        let filters = p.stages.iter().any(|s| matches!(s, Stage::Filter(_)));
        // Before the loop.
        match &p.sink {
            Sink::Reduce(_, init) => {
                let acc = self.expr_as(init, &result)?;
                body.push_str(&format!("{pad}\t{n}acc := {acc}\n"));
            }
            Sink::FindIndex(_) => body.push_str(&format!("{pad}\t{n}k := 0\n")),
            Sink::Collect(_) => {
                let GoType::Array(elem) = &result else {
                    return Err(unsupported("array pipeline of a non-array type", span));
                };
                let t = self.tm.render(elem);
                if filters {
                    body.push_str(&format!("{pad}\t{n}out := []{t}{{}}\n"));
                } else {
                    body.push_str(&format!("{pad}\t{n}out := make([]{t}, 0, len(*{n}src))\n"));
                }
            }
            _ => {}
        }
        body.push_str(&format!("{pad}\tfor _, {n}x := range *{n}src {{\n"));
        let mut x = format!("{n}x");
        for (i, st) in p.stages.iter().enumerate() {
            match st {
                Stage::Map(_) => {
                    let y = format!("{n}x{i}");
                    body.push_str(&format!("{pad}\t\t{y} := {n}f{i}({x})\n"));
                    x = y;
                }
                Stage::Filter(_) => {
                    body.push_str(&format!(
                        "{pad}\t\tif !{n}f{i}({x}) {{\n{pad}\t\t\tcontinue\n{pad}\t\t}}\n"
                    ));
                }
            }
        }
        let (each, after, ret) = match &p.sink {
            Sink::Reduce(..) => (
                format!("{n}acc = {n}s({n}acc, {x})"),
                format!("return {n}acc"),
                true,
            ),
            Sink::ForEach(_) => (format!("{n}s({x})"), String::new(), false),
            Sink::Some(_) => (
                format!("if {n}s({x}) {{ return true }}"),
                "return false".into(),
                true,
            ),
            Sink::Every(_) => (
                format!("if !{n}s({x}) {{ return false }}"),
                "return true".into(),
                true,
            ),
            Sink::FindIndex(_) => (
                format!(
                    "if {n}s({x}) {{ return {} }}\n{pad}\t\t{n}k++",
                    coerce(format!("{n}k"), &GoType::Int, &result)
                ),
                format!("return {}", coerce("(-1)".into(), &GoType::Int, &result)),
                true,
            ),
            Sink::Collect(_) => {
                let grow = if filters {
                    format!(
                        "if len({n}out) == cap({n}out) {{ {n}out = intyGrow({n}out) }}\n{pad}\t\t"
                    )
                } else {
                    String::new()
                };
                (
                    format!("{grow}{n}out = append({n}out, {x})"),
                    format!("return &{n}out"),
                    true,
                )
            }
        };
        body.push_str(&format!("{pad}\t\t{each}\n{pad}\t}}\n"));
        if !after.is_empty() {
            body.push_str(&format!("{pad}\t{after}\n"));
        }
        let sig = if ret {
            format!("func() {} ", self.tm.render(&result))
        } else {
            "func() ".to_string()
        };
        Ok(format!("{sig}{{\n{body}{pad}}}()"))
    }

    /// `stmt` as `const name = <map/filter chain>` whose only use is as
    /// the source of a pipeline that `rest[0]` evaluates first thing (the
    /// whole value of a declaration, a `return`, an assignment or an
    /// expression statement): then it needn't exist as an array.
    fn fusible_intermediate(&mut self, stmt: &Stmt, rest: &[Stmt]) -> Option<(String, Expr)> {
        let Stmt::Var {
            kind: VarKind::Const,
            declarations,
            ..
        } = stmt
        else {
            return None;
        };
        let [d] = declarations.as_slice() else {
            return None;
        };
        let init = d.init.as_ref()?;
        // The declaration itself must be a map/filter chain of pure steps.
        let Expr::Call { callee, .. } = init else {
            return None;
        };
        match &**callee {
            Expr::Member { property, .. } if property == "map" || property == "filter" => {}
            _ => return None,
        }
        let (next, later) = rest.split_first()?;
        let uses = inty::ast::free_idents::free_identifier_counts_in_stmt(next);
        if uses.get(&d.name).copied() != Some(1)
            || later
                .iter()
                .any(|s| free_identifiers_in_stmt(s).contains(&d.name))
        {
            return None;
        }
        let consumer = match next {
            Stmt::Var { declarations, .. } => match declarations.as_slice() {
                [c] => c.init.as_ref()?,
                _ => return None,
            },
            Stmt::Return {
                argument: Some(a), ..
            } => a,
            Stmt::Expr { expression, .. } => match expression {
                Expr::Assign { left, right, .. } if is_pure_place(left) => right,
                other => other,
            },
            _ => return None,
        };
        // Check with the declaration deferred, as the consumer will see it.
        self.deferred.insert(d.name.clone(), init.clone());
        let ok = self.pipeline_source_is(consumer, &d.name) && self.pipeline(consumer).is_some();
        self.deferred.remove(&d.name);
        // The deferred chain itself must be pure too.
        let own = matches!(self.pipeline_steps_pure(init), Some(true));
        (ok && own).then(|| (d.name.clone(), init.clone()))
    }

    /// Whether the innermost source of the chain `e` is the name `name`.
    fn pipeline_source_is(&self, e: &Expr, name: &str) -> bool {
        let mut cur = e;
        loop {
            match cur {
                Expr::Call { callee, .. } => match &**callee {
                    Expr::Member { object, .. } => cur = object,
                    _ => return false,
                },
                Expr::Ident { name: n, .. } => return n == name,
                _ => return false,
            }
        }
    }

    /// For a map/filter chain: whether all its callbacks are pure.
    fn pipeline_steps_pure(&mut self, e: &Expr) -> Option<bool> {
        let mut cur = e;
        loop {
            match cur {
                Expr::Call {
                    callee, arguments, ..
                } => match (&**callee, arguments.as_slice()) {
                    (
                        Expr::Member {
                            object, property, ..
                        },
                        [f],
                    ) if property == "map" || property == "filter" => {
                        if !self.pure_callback(f) {
                            return Some(false);
                        }
                        cur = object;
                    }
                    _ => return Some(true),
                },
                _ => return Some(true),
            }
        }
    }

    /// A function literal whose calls have no effect anything can see.
    fn pure_callback(&mut self, f: &Expr) -> bool {
        match f {
            Expr::Function {
                name: None,
                params,
                body,
                ..
            } => {
                let mut locals: Vec<String> = params.iter().map(|p| p.name.clone()).collect();
                self.pure_stmt(body, &mut locals)
            }
            // `xs.map(square)`: a pure function by name.
            Expr::Ident { name, .. } => self.pure_func(name),
            _ => false,
        }
    }

    /// A top-level (or block-level) function whose calls are pure. A
    /// recursive reference is assumed pure while it's being checked.
    fn pure_func(&mut self, name: &str) -> bool {
        if let Some(&p) = self.pure_funcs.get(name) {
            return p;
        }
        let Some(Bound::Func(fid)) = self.lookup(name) else {
            return false;
        };
        self.pure_funcs.insert(name.to_string(), true);
        let params = self.funcs[fid].params.clone();
        let body = self.funcs[fid].body.clone();
        let mut locals: Vec<String> = params.iter().map(|p| p.name.clone()).collect();
        let pure = self.pure_stmt(&body, &mut locals);
        self.pure_funcs.insert(name.to_string(), pure);
        pure
    }

    fn pure_stmt(&mut self, s: &Stmt, locals: &mut Vec<String>) -> bool {
        match s {
            Stmt::Empty { .. } | Stmt::Break { .. } | Stmt::Continue { .. } => true,
            Stmt::Block { body, .. } => {
                let n = locals.len();
                let ok = body.iter().all(|s| self.pure_stmt(s, locals));
                locals.truncate(n);
                ok
            }
            Stmt::Expr { expression, .. } => self.pure_expr(expression, locals),
            Stmt::Var { declarations, .. } => declarations.iter().all(|d| {
                let ok = d.init.as_ref().is_none_or(|e| self.pure_expr(e, locals));
                locals.push(d.name.clone());
                ok
            }),
            Stmt::Return { argument, .. } => {
                argument.as_ref().is_none_or(|e| self.pure_expr(e, locals))
            }
            Stmt::If {
                test,
                consequent,
                alternate,
                ..
            } => {
                self.pure_expr(test, locals)
                    && self.pure_stmt(consequent, locals)
                    && alternate
                        .as_deref()
                        .is_none_or(|a| self.pure_stmt(a, locals))
            }
            Stmt::While { test, body, .. } | Stmt::DoWhile { body, test, .. } => {
                self.pure_expr(test, locals) && self.pure_stmt(body, locals)
            }
            Stmt::For {
                init,
                test,
                update,
                body,
                ..
            } => {
                let n = locals.len();
                let ok = match init {
                    None => true,
                    Some(ForInit::Expr(e)) => self.pure_expr(e, locals),
                    Some(ForInit::VarDecl(ds)) => ds.iter().all(|d| {
                        let ok = d.init.as_ref().is_none_or(|e| self.pure_expr(e, locals));
                        locals.push(d.name.clone());
                        ok
                    }),
                } && test.as_ref().is_none_or(|t| self.pure_expr(t, locals))
                    && update.as_ref().is_none_or(|u| self.pure_expr(u, locals))
                    && self.pure_stmt(body, locals);
                locals.truncate(n);
                ok
            }
            _ => false,
        }
    }

    fn pure_expr(&mut self, e: &Expr, locals: &mut Vec<String>) -> bool {
        let is_local = |e: &Expr, locals: &[String]| matches!(e, Expr::Ident { name, .. } if locals.contains(name));
        match e {
            Expr::Lit { .. } | Expr::Ident { .. } => true,
            Expr::Unary { op, argument, .. } => match op {
                UnaryOp::PreInc | UnaryOp::PreDec | UnaryOp::PostInc | UnaryOp::PostDec => {
                    is_local(argument, locals)
                }
                UnaryOp::Delete => false,
                _ => self.pure_expr(argument, locals),
            },
            Expr::Binary { left, right, .. } => {
                self.pure_expr(left, locals) && self.pure_expr(right, locals)
            }
            Expr::Assign { left, right, .. } => {
                is_local(left, locals) && self.pure_expr(right, locals)
            }
            Expr::Conditional {
                test,
                consequent,
                alternate,
                ..
            } => {
                self.pure_expr(test, locals)
                    && self.pure_expr(consequent, locals)
                    && self.pure_expr(alternate, locals)
            }
            Expr::Member { object, .. } => self.pure_expr(object, locals),
            Expr::ComputedMember {
                object, property, ..
            } => self.pure_expr(object, locals) && self.pure_expr(property, locals),
            Expr::Array { elements, .. } => elements
                .iter()
                .all(|el| el.as_ref().is_some_and(|x| self.pure_expr(x, locals))),
            Expr::Object { properties, .. } => properties.iter().all(|p| match p {
                PropDef::Property { value, .. } => self.pure_expr(value, locals),
                _ => false,
            }),
            Expr::TemplateLiteral { expressions, .. } => {
                expressions.iter().all(|x| self.pure_expr(x, locals))
            }
            Expr::Call {
                callee, arguments, ..
            } => {
                if !arguments.iter().all(|a| self.pure_expr(a, locals)) {
                    return false;
                }
                match &**callee {
                    Expr::Ident { name, .. } => {
                        matches!(name.as_str(), "String" | "isNaN") || self.pure_func(name)
                    }
                    Expr::Member {
                        object, property, ..
                    } => {
                        if let Expr::Ident { name, .. } = &**object {
                            match (name.as_str(), property.as_str()) {
                                ("Math", "random") => return false,
                                ("Math", _) => return true,
                                ("Number", "isInteger") | ("String", "fromCharCode") => {
                                    return true
                                }
                                _ => {}
                            }
                        }
                        if !self.pure_expr(object, locals) {
                            return false;
                        }
                        match self.type_of(object) {
                            Ok(GoType::Str) => true,
                            Ok(GoType::Array(_)) => matches!(
                                property.as_str(),
                                "indexOf" | "includes" | "slice" | "join" | "concat"
                            ),
                            _ => false,
                        }
                    }
                    _ => false,
                }
            }
            _ => false,
        }
    }
}

/// One step of an array pipeline, by its callback.
#[derive(Clone)]
enum Stage {
    Map(Expr),
    Filter(Expr),
}

/// What consumes a pipeline's elements.
#[derive(Clone)]
enum Sink {
    Reduce(Expr, Expr),
    ForEach(Expr),
    Some(Expr),
    Every(Expr),
    FindIndex(Expr),
    /// The elements as an array (the chain's last step is its first entry
    /// until `pipeline` moves it into the stages).
    Collect(Option<Stage>),
}

impl Sink {
    fn callback(&self) -> Option<&Expr> {
        match self {
            Sink::Reduce(f, _)
            | Sink::ForEach(f)
            | Sink::Some(f)
            | Sink::Every(f)
            | Sink::FindIndex(f) => Some(f),
            Sink::Collect(_) => None,
        }
    }
}

struct Pipeline {
    source: Expr,
    stages: Vec<Stage>,
    sink: Sink,
}
